i already have this app but it needs some work. i want it so its not split 50/50 but so the left side takes up 1/3 of the screen and is retractable so that it can disappear and appear with the click of a little button, similar to ai chat sidebars. in this left section it should work the same way. you can remove the image section in the excercises and remove the notes as well.
also on the right side in the routine builder i want it to be more compact it should only take one line of space and show the name of the excercise then the category and then the description next to that in one line. you can remove the extra comment section for reps sets weight etc.
also a button for them to expand would be nice so you can have them collapsed so its only the title of the routine or expand so you see all the excercises.
heres the code:

'use client';

import React, { useState, useEffect } from 'react';
import { Plus, Edit2, Trash2, Upload, Download, Star, MessageSquare, Tag, GripVertical } from 'lucide-react';

const DEFAULT_CATEGORIES = [
  { name: 'Mobility', color: 'bg-blue-500' },
  { name: 'Strengthening', color: 'bg-green-500' },
  { name: 'Deep Stabilizers', color: 'bg-purple-500' },
  { name: 'Cardio', color: 'bg-red-500' },
  { name: 'Breathing', color: 'bg-yellow-500' },
  { name: 'Release', color: 'bg-pink-500' },
  { name: 'Nervous System', color: 'bg-indigo-500' }
];

const COLORS = ['bg-blue-500', 'bg-green-500', 'bg-purple-500', 'bg-red-500', 'bg-yellow-500', 'bg-pink-500', 'bg-indigo-500', 'bg-orange-500', 'bg-teal-500', 'bg-cyan-500'];

interface Exercise {
  id: number;
  title: string;
  description: string;
  category: string;
  videoUrl: string;
  imageUrl: string;
  rating: number;
  notes: string;
}

interface ExerciseItem {
  exerciseId: number;
  routineNotes: string;
}

interface SubRoutine {
  id: number;
  name: string;
  exerciseItems: ExerciseItem[];
}

interface Routine {
  id: number;
  name: string;
  exerciseItems: ExerciseItem[];
  subRoutines: SubRoutine[];
}

interface Category {
  name: string;
  color: string;
}

export default function Page() {
  const [view, setView] = useState<'main' | 'categories'>('main');
  const [exercises, setExercises] = useState<Exercise[]>([]);
  const [routines, setRoutines] = useState<Routine[]>([]);
  const [categories, setCategories] = useState<Category[]>(DEFAULT_CATEGORIES);

  const [showAddExercise, setShowAddExercise] = useState(false);
  const [editingExercise, setEditingExercise] = useState<Exercise | null>(null);
  const [newExercise, setNewExercise] = useState<Exercise>({
    id: 0,
    title: '',
    description: '',
    category: 'Mobility',
    videoUrl: '',
    imageUrl: '',
    rating: 0,
    notes: ''
  });

  const [showAddCategory, setShowAddCategory] = useState(false);
  const [newCategoryName, setNewCategoryName] = useState('');
  const [selectedColor, setSelectedColor] = useState(COLORS[0]);

  const [draggedExercise, setDraggedExercise] = useState<Exercise | null>(null);
  const [draggedRoutineIndex, setDraggedRoutineIndex] = useState<number | null>(null);

  // Load data
  useEffect(() => {
    try {
      const exercisesData = localStorage.getItem('exercises');
      if (exercisesData) setExercises(JSON.parse(exercisesData));

      const routinesData = localStorage.getItem('routines_v2');
      if (routinesData) setRoutines(JSON.parse(routinesData));

      const categoriesData = localStorage.getItem('categories');
      if (categoriesData) setCategories(JSON.parse(categoriesData));
    } catch (error) {
      console.log('No saved data');
    }
  }, []);

  // Save data
  useEffect(() => {
    try {
      localStorage.setItem('exercises', JSON.stringify(exercises));
      localStorage.setItem('routines_v2', JSON.stringify(routines));
      localStorage.setItem('categories', JSON.stringify(categories));
    } catch (error) {
      console.error('Error saving:', error);
    }
  }, [exercises, routines, categories]);

  // Exercise CRUD
  const addExercise = () => {
    if (!newExercise.title.trim()) return;
    const exercise = { ...newExercise, id: Date.now() };
    setExercises([...exercises, exercise]);
    setNewExercise({ id: 0, title: '', description: '', category: categories[0].name, videoUrl: '', imageUrl: '', rating: 0, notes: '' });
    setShowAddExercise(false);
  };

  const updateExercise = () => {
    if (!editingExercise) return;
    setExercises(exercises.map(ex => ex.id === editingExercise.id ? editingExercise : ex));
    setEditingExercise(null);
    setShowAddExercise(false);
  };

  const deleteExercise = (id: number) => {
    setExercises(exercises.filter(ex => ex.id !== id));
    setRoutines(routines.map(r => ({
      ...r,
      exerciseItems: r.exerciseItems.filter(item => item.exerciseId !== id),
      subRoutines: r.subRoutines.map(sr => ({
        ...sr,
        exerciseItems: sr.exerciseItems.filter(item => item.exerciseId !== id)
      }))
    })));
  };

  // Category CRUD
  const addCategory = () => {
    if (!newCategoryName.trim()) return;
    setCategories([...categories, { name: newCategoryName, color: selectedColor }]);
    setNewCategoryName('');
    setShowAddCategory(false);
  };

  const deleteCategory = (name: string) => {
    setCategories(categories.filter(c => c.name !== name));
  };

  const getCategoryColor = (category: string) => {
    return categories.find(c => c.name === category)?.color || 'bg-gray-500';
  };

  // Routine CRUD
  const createRoutine = () => {
    const routine: Routine = {
      id: Date.now(),
      name: 'New Routine',
      exerciseItems: [],
      subRoutines: []
    };
    setRoutines([...routines, routine]);
  };

  const deleteRoutine = (id: number) => {
    setRoutines(routines.filter(r => r.id !== id));
  };

  const updateRoutineName = (id: number, name: string) => {
    setRoutines(routines.map(r => r.id === id ? { ...r, name } : r));
  };

  const addSubRoutine = (routineId: number) => {
    setRoutines(routines.map(r => {
      if (r.id === routineId) {
        return {
          ...r,
          subRoutines: [...r.subRoutines, { id: Date.now(), name: 'New Section', exerciseItems: [] }]
        };
      }
      return r;
    }));
  };

  const deleteSubRoutine = (routineId: number, subRoutineId: number) => {
    setRoutines(routines.map(r => {
      if (r.id === routineId) {
        return {
          ...r,
          subRoutines: r.subRoutines.filter(sr => sr.id !== subRoutineId)
        };
      }
      return r;
    }));
  };

  const updateSubRoutineName = (routineId: number, subRoutineId: number, name: string) => {
    setRoutines(routines.map(r => {
      if (r.id === routineId) {
        return {
          ...r,
          subRoutines: r.subRoutines.map(sr => sr.id === subRoutineId ? { ...sr, name } : sr)
        };
      }
      return r;
    }));
  };

  // Drag handlers for exercises
  const handleExerciseDragStart = (exercise: Exercise) => {
    setDraggedExercise(exercise);
  };

  const handleExerciseDragEnd = () => {
    setDraggedExercise(null);
  };

  const handleDropOnRoutine = (routineId: number) => {
    if (!draggedExercise) return;
    setRoutines(routines.map(r => {
      if (r.id === routineId) {
        const exists = r.exerciseItems.find(item => item.exerciseId === draggedExercise.id);
        if (!exists) {
          return {
            ...r,
            exerciseItems: [...r.exerciseItems, { exerciseId: draggedExercise.id, routineNotes: '' }]
          };
        }
      }
      return r;
    }));
    setDraggedExercise(null);
  };

  const handleDropOnSubRoutine = (routineId: number, subRoutineId: number) => {
    if (!draggedExercise) return;
    setRoutines(routines.map(r => {
      if (r.id === routineId) {
        return {
          ...r,
          subRoutines: r.subRoutines.map(sr => {
            if (sr.id === subRoutineId) {
              const exists = sr.exerciseItems.find(item => item.exerciseId === draggedExercise.id);
              if (!exists) {
                return {
                  ...sr,
                  exerciseItems: [...sr.exerciseItems, { exerciseId: draggedExercise.id, routineNotes: '' }]
                };
              }
            }
            return sr;
          })
        };
      }
      return r;
    }));
    setDraggedExercise(null);
  };

  const removeExerciseFromRoutine = (routineId: number, exerciseId: number) => {
    setRoutines(routines.map(r => {
      if (r.id === routineId) {
        return {
          ...r,
          exerciseItems: r.exerciseItems.filter(item => item.exerciseId !== exerciseId)
        };
      }
      return r;
    }));
  };

  const removeExerciseFromSubRoutine = (routineId: number, subRoutineId: number, exerciseId: number) => {
    setRoutines(routines.map(r => {
      if (r.id === routineId) {
        return {
          ...r,
          subRoutines: r.subRoutines.map(sr => {
            if (sr.id === subRoutineId) {
              return {
                ...sr,
                exerciseItems: sr.exerciseItems.filter(item => item.exerciseId !== exerciseId)
              };
            }
            return sr;
          })
        };
      }
      return r;
    }));
  };

  const updateRoutineNotes = (routineId: number, exerciseId: number, notes: string) => {
    setRoutines(routines.map(r => {
      if (r.id === routineId) {
        return {
          ...r,
          exerciseItems: r.exerciseItems.map(item =>
            item.exerciseId === exerciseId ? { ...item, routineNotes: notes } : item
          )
        };
      }
      return r;
    }));
  };

  const updateSubRoutineNotes = (routineId: number, subRoutineId: number, exerciseId: number, notes: string) => {
    setRoutines(routines.map(r => {
      if (r.id === routineId) {
        return {
          ...r,
          subRoutines: r.subRoutines.map(sr => {
            if (sr.id === subRoutineId) {
              return {
                ...sr,
                exerciseItems: sr.exerciseItems.map(item =>
                  item.exerciseId === exerciseId ? { ...item, routineNotes: notes } : item
                )
              };
            }
            return sr;
          })
        };
      }
      return r;
    }));
  };

  // Drag handlers for routines
  const handleRoutineDragStart = (index: number) => {
    setDraggedRoutineIndex(index);
  };

  const handleRoutineDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedRoutineIndex === null || draggedRoutineIndex === index) return;

    const items = [...routines];
    const draggedItem = items[draggedRoutineIndex];
    items.splice(draggedRoutineIndex, 1);
    items.splice(index, 0, draggedItem);

    setRoutines(items);
    setDraggedRoutineIndex(index);
  };

  const handleRoutineDragEnd = () => {
    setDraggedRoutineIndex(null);
  };

  // Group exercises by category
  const exercisesByCategory = categories.map(cat => ({
    category: cat,
    exercises: exercises.filter(ex => ex.category === cat.name)
  }));

  const StarRating = ({ rating, onRate }: { rating: number; onRate?: (rating: number) => void }) => (
    <div className="flex gap-1">
      {[1, 2, 3, 4, 5].map(star => (
        <button
          key={star}
          onClick={() => onRate?.(star)}
          className={`${rating >= star ? 'text-yellow-400' : 'text-gray-300'} ${onRate ? 'hover:text-yellow-400' : ''}`}
          type="button"
        >
          <Star size={18} fill={rating >= star ? 'currentColor' : 'none'} />
        </button>
      ))}
    </div>
  );

  const exportData = () => {
    const data = exercises.map(ex => ({
      Title: ex.title,
      Description: ex.description,
      Category: ex.category,
      'Video URL': ex.videoUrl,
      'Image URL': ex.imageUrl,
      Rating: ex.rating,
      Notes: ex.notes
    }));

    const csv = [
      Object.keys(data[0] || {}).join(','),
      ...data.map(row => Object.values(row).map(v => `"${v}"`).join(','))
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'exercises.csv';
    a.click();
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      const rows = text.split('\n').filter(row => row.trim());
      const headers = rows[0].split(',').map(h => h.trim().replace(/"/g, ''));

      const imported = rows.slice(1).map(row => {
        const values = row.match(/(".*?"|[^,]+)(?=\s*,|\s*$)/g)?.map(v => v.trim().replace(/^"|"$/g, '')) || [];
        const obj: any = {};
        headers.forEach((header, i) => {
          obj[header] = values[i] || '';
        });

        return {
          id: Date.now() + Math.random(),
          title: obj.Title || '',
          description: obj.Description || '',
          category: obj.Category || categories[0].name,
          videoUrl: obj['Video URL'] || '',
          imageUrl: obj['Image URL'] || '',
          rating: parseInt(obj.Rating) || 0,
          notes: obj.Notes || ''
        };
      });

      setExercises([...exercises, ...imported]);
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="bg-white border-b sticky top-0 z-10">
        <div className="max-w-full mx-auto px-4 py-4">
          <h1 className="text-2xl font-bold text-gray-900 mb-4">Neck Exercise Tracker</h1>
          <div className="flex gap-2">
            <button
              onClick={() => setView('main')}
              className={`px-4 py-2 rounded-lg font-medium transition ${
                view === 'main' ? 'bg-blue-500 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              Library & Routines
            </button>
            <button
              onClick={() => setView('categories')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition ${
                view === 'categories' ? 'bg-blue-500 text-white' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              <Tag size={20} /> Categories
            </button>
          </div>
        </div>
      </div>

      {/* Main Split View */}
      {view === 'main' && (
        <div className="flex h-[calc(100vh-140px)]">
          {/* LEFT SIDE - Exercise Library */}
          <div className="w-1/2 border-r border-gray-200 overflow-y-auto">
            <div className="p-4">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-xl font-bold">Exercise Library</h2>
                <div className="flex gap-2">
                  <button
                    onClick={() => setShowAddExercise(true)}
                    className="flex items-center gap-2 px-3 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 text-sm"
                  >
                    <Plus size={16} /> Add
                  </button>
                  <label className="flex items-center gap-2 px-3 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 cursor-pointer text-sm">
                    <Upload size={16} /> Import
                    <input type="file" accept=".csv" onChange={importData} className="hidden" />
                  </label>
                  {exercises.length > 0 && (
                    <button
                      onClick={exportData}
                      className="flex items-center gap-2 px-3 py-2 bg-purple-500 text-white rounded-lg hover:bg-purple-600 text-sm"
                    >
                      <Download size={16} /> Export
                    </button>
                  )}
                </div>
              </div>

              {/* Add Exercise Form */}
              {(showAddExercise || editingExercise) && (
                <div className="bg-white p-4 rounded-lg shadow-md mb-4 border">
                  <h3 className="text-lg font-semibold mb-3">{editingExercise ? 'Edit' : 'New'} Exercise</h3>
                  <div className="space-y-3">
                    <input
                      type="text"
                      placeholder="Title"
                      value={editingExercise ? editingExercise.title : newExercise.title}
                      onChange={(e) => editingExercise 
                        ? setEditingExercise({...editingExercise, title: e.target.value})
                        : setNewExercise({...newExercise, title: e.target.value})
                      }
                      className="w-full px-3 py-2 border rounded-lg text-sm"
                    />
                    <textarea
                      placeholder="Description"
                      value={editingExercise ? editingExercise.description : newExercise.description}
                      onChange={(e) => editingExercise
                        ? setEditingExercise({...editingExercise, description: e.target.value})
                        : setNewExercise({...newExercise, description: e.target.value})
                      }
                      rows={2}
                      className="w-full px-3 py-2 border rounded-lg text-sm"
                    />
                    <select
                      value={editingExercise ? editingExercise.category : newExercise.category}
                      onChange={(e) => editingExercise
                        ? setEditingExercise({...editingExercise, category: e.target.value})
                        : setNewExercise({...newExercise, category: e.target.value})
                      }
                      className="w-full px-3 py-2 border rounded-lg text-sm"
                    >
                      {categories.map(cat => <option key={cat.name}>{cat.name}</option>)}
                    </select>
                    <input
                      type="text"
                      placeholder="Video URL"
                      value={editingExercise ? editingExercise.videoUrl : newExercise.videoUrl}
                      onChange={(e) => editingExercise
                        ? setEditingExercise({...editingExercise, videoUrl: e.target.value})
                        : setNewExercise({...newExercise, videoUrl: e.target.value})
                      }
                      className="w-full px-3 py-2 border rounded-lg text-sm"
                    />
                    <input
                      type="text"
                      placeholder="Image URL"
                      value={editingExercise ? editingExercise.imageUrl : newExercise.imageUrl}
                      onChange={(e) => editingExercise
                        ? setEditingExercise({...editingExercise, imageUrl: e.target.value})
                        : setNewExercise({...newExercise, imageUrl: e.target.value})
                      }
                      className="w-full px-3 py-2 border rounded-lg text-sm"
                    />
                    <div>
                      <label className="block text-sm font-medium mb-1">Rating</label>
                      <StarRating
                        rating={editingExercise ? editingExercise.rating : newExercise.rating}
                        onRate={(rating) => editingExercise
                          ? setEditingExercise({...editingExercise, rating})
                          : setNewExercise({...newExercise, rating})
                        }
                      />
                    </div>
                    <textarea
                      placeholder="Notes"
                      value={editingExercise ? editingExercise.notes : newExercise.notes}
                      onChange={(e) => editingExercise
                        ? setEditingExercise({...editingExercise, notes: e.target.value})
                        : setNewExercise({...newExercise, notes: e.target.value})
                      }
                      rows={2}
                      className="w-full px-3 py-2 border rounded-lg text-sm"
                    />
                    <div className="flex gap-2">
                      <button
                        onClick={editingExercise ? updateExercise : addExercise}
                        className="px-3 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 text-sm"
                      >
                        {editingExercise ? 'Update' : 'Add'}
                      </button>
                      <button
                        onClick={() => {
                          setShowAddExercise(false);
                          setEditingExercise(null);
                          setNewExercise({ id: 0, title: '', description: '', category: categories[0]?.name || 'Mobility', videoUrl: '', imageUrl: '', rating: 0, notes: '' });
                        }}
                        className="px-3 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 text-sm"
                      >
                        Cancel
                      </button>
                    </div>
                  </div>
                </div>
              )}

              {/* Exercises grouped by category */}
              <div className="space-y-4">
                {exercisesByCategory.map(({ category, exercises: catExercises }) => (
                  catExercises.length > 0 && (
                    <div key={category.name} className="bg-white rounded-lg shadow-sm border p-3">
                      <div className="flex items-center gap-2 mb-3">
                        <div className={`w-4 h-4 rounded ${category.color}`} />
                        <h3 className="font-semibold">{category.name}</h3>
                        <span className="text-sm text-gray-400">({catExercises.length})</span>
                      </div>
                      <div className="space-y-2">
                        {catExercises.map(ex => (
                          <div
                            key={ex.id}
                            draggable
                            onDragStart={() => handleExerciseDragStart(ex)}
                            onDragEnd={handleExerciseDragEnd}
                            className="flex items-start gap-2 p-2 bg-gray-50 rounded border hover:bg-gray-100 cursor-move"
                          >
                            <GripVertical size={16} className="text-gray-400 flex-shrink-0 mt-1" />
                            <div className="flex-1 min-w-0">
                              <div className="font-medium text-sm truncate">{ex.title}</div>
                              {ex.description && <div className="text-xs text-gray-600 truncate">{ex.description}</div>}
                              {ex.rating > 0 && (
                                <div className="flex items-center gap-1 mt-1">
                                  <Star size={12} className="text-yellow-400" fill="currentColor" />
                                  <span className="text-xs text-gray-600">{ex.rating}/5</span>
                                </div>
                              )}
                            </div>
                            <div className="flex gap-1">
                              <button
                                onClick={() => {
                                  setEditingExercise(ex);
                                  setShowAddExercise(true);
                                }}
                                className="p-1 bg-white rounded hover:bg-gray-200"
                              >
                                <Edit2 size={14} />
                              </button>
                              <button
                                onClick={() => deleteExercise(ex.id)}
                                className="p-1 bg-white rounded hover:bg-red-100 text-red-500"
                              >
                                <Trash2 size={14} />
                              </button>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  )
                ))}
                {exercises.length === 0 && (
                  <div className="text-center py-12 text-gray-400">
                    No exercises yet. Add your first one!
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* RIGHT SIDE - Routines */}
          <div className="w-1/2 overflow-y-auto bg-gray-50">
            <div className="p-4">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-xl font-bold">Routines</h2>
                <button
                  onClick={createRoutine}
                  className="flex items-center gap-2 px-3 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 text-sm"
                >
                  <Plus size={16} /> New Routine
                </button>
              </div>

              {/* Routines List */}
              <div className="space-y-4">
                {routines.map((routine, ridx) => (
                  <div
                    key={routine.id}
                    draggable
                    onDragStart={() => handleRoutineDragStart(ridx)}
                    onDragOver={(e) => handleRoutineDragOver(e, ridx)}
                    onDragEnd={handleRoutineDragEnd}
                    className="bg-white rounded-lg shadow-sm border"
                  >
                    {/* Routine Header */}
                    <div className="flex items-center gap-2 p-3 border-b bg-gray-50 cursor-move">
                      <GripVertical size={20} className="text-gray-400" />
                      <input
                        type="text"
                        value={routine.name}
                        onChange={(e) => updateRoutineName(routine.id, e.target.value)}
                        className="flex-1 font-semibold text-lg bg-transparent border-none focus:outline-none focus:ring-2 focus:ring-blue-200 rounded px-2"
                        onClick={(e) => e.stopPropagation()}
                      />
                      <button
                        onClick={() => addSubRoutine(routine.id)}
                        className="px-2 py-1 bg-blue-100 text-blue-600 rounded hover:bg-blue-200 text-xs"
                      >
                        + Section
                      </button>
                      <button
                        onClick={() => deleteRoutine(routine.id)}
                        className="p-2 text-red-500 hover:bg-red-50 rounded"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>

                    {/* Routine Body */}
                    <div className="p-3">
                      {/* Main Exercises (no section) */}
                      <div
                        onDragOver={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                        }}
                        onDrop={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          handleDropOnRoutine(routine.id);
                        }}
