            <div className="flex gap-2 pt-2">
              <button 
                onClick={handleSave}
                className="flex-1 py-2 bg-blue-600 text-white rounded-lg text-sm font-semibold hover:bg-blue-700 shadow-sm"
              >
                {editingId ? 'Save Changes' : 'Add to Library'}
              </button>
            </div>
          </div>
        )}

        {grouped.length === 0 ? (
          <div className="text-center py-10">
            <p className="text-gray-400 text-sm">No exercises found.</p>
          </div>
        ) : (
          grouped.map(({ category, items }) => (
            <div key={category.name} className="space-y-2">
              <div className="flex items-center gap-2 px-1">
                <div className={`w-2 h-2 rounded-full ${category.color}`} />
                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest">{category.name}</h4>
              </div>
              <div className="space-y-1.5">
                {items.map(ex => (
                  <div 
                    key={ex.id}
                    draggable
                    onDragStart={(e) => {
                      e.dataTransfer.setData('exerciseId', ex.id.toString());
                    }}
                    className="group flex items-center gap-2 p-3 bg-white border border-gray-100 rounded-xl hover:border-blue-200 hover:shadow-md transition-all cursor-grab active:cursor-grabbing"
                  >
                    <GripVertical size={16} className="text-gray-300 group-hover:text-blue-400 transition-colors" />
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-semibold text-gray-700 truncate">{ex.title}</p>
                      {ex.rating > 0 && (
                        <div className="flex items-center gap-0.5 mt-0.5">
                          {[...Array(ex.rating)].map((_, i) => (
                            <div key={i} className="w-1.5 h-1.5 rounded-full bg-yellow-400" />
                          ))}
                        </div>
                      )}
                    </div>
                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button 
                        onClick={() => handleEdit(ex)}
                        className="p-1.5 hover:bg-gray-100 rounded-lg text-gray-400 hover:text-blue-500"
                      >
                        <Edit2 size={14} />
                      </button>
                      <button 
                        onClick={() => handleDelete(ex.id)}
                        className="p-1.5 hover:bg-red-50 rounded-lg text-gray-400 hover:text-red-500"
                      >
                        <Trash2 size={14} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default Sidebar;

import React from 'react';
import { 
  Plus, 
  Trash2, 
  ChevronDown, 
  ChevronRight, 
  GripVertical,
  Layers
} from 'lucide-react';
import { Routine, Exercise, Category, SubRoutine } from '../types';

interface RoutineBuilderProps {
  routines: Routine[];
  setRoutines: React.Dispatch<React.SetStateAction<Routine[]>>;
  exercises: Exercise[];
  categories: Category[];
}

const RoutineBuilder: React.FC<RoutineBuilderProps> = ({ routines, setRoutines, exercises, categories }) => {

  const createRoutine = () => {
    const newRoutine: Routine = {
      id: Date.now(),
      name: 'New Routine',
      exerciseItems: [],
      subRoutines: [],
      isExpanded: true
    };
    setRoutines([newRoutine, ...routines]);
  };

  const updateRoutine = (id: number, updates: Partial<Routine>) => {
    setRoutines(prev => prev.map(r => r.id === id ? { ...r, ...updates } : r));
  };

  const deleteRoutine = (id: number) => {
    if (confirm("Delete this entire routine?")) {
      setRoutines(prev => prev.filter(r => r.id !== id));
    }
  };

  const addSection = (routineId: number) => {
    setRoutines(prev => prev.map(r => {
      if (r.id === routineId) {
        return {
          ...r,
          subRoutines: [...r.subRoutines, { id: Date.now(), name: 'New Section', exerciseItems: [], isExpanded: true }]
        };
      }
      return r;
    }));
  };

  const handleDrop = (e: React.DragEvent, routineId: number, subRoutineId?: number) => {
    e.preventDefault();
    const exerciseId = parseInt(e.dataTransfer.getData('exerciseId'));
    if (!exerciseId) return;

    setRoutines(prev => prev.map(r => {
      if (r.id === routineId) {
        if (subRoutineId) {
          return {
            ...r,
            subRoutines: r.subRoutines.map(sr => {
              if (sr.id === subRoutineId) {
                return { ...sr, exerciseItems: [...sr.exerciseItems, { exerciseId }] };
              }
              return sr;
            })
          };
        } else {
          return { ...r, exerciseItems: [...r.exerciseItems, { exerciseId }] };
        }
      }
      return r;
    }));
  };

  const removeExercise = (routineId: number, index: number, subRoutineId?: number) => {
    setRoutines(prev => prev.map(r => {
      if (r.id === routineId) {
        if (subRoutineId) {
          return {
            ...r,
            subRoutines: r.subRoutines.map(sr => {
              if (sr.id === subRoutineId) {
                const newItems = [...sr.exerciseItems];
                newItems.splice(index, 1);
                return { ...sr, exerciseItems: newItems };
              }
              return sr;
            })
          };
        } else {
          const newItems = [...r.exerciseItems];
          newItems.splice(index, 1);
          return { ...r, exerciseItems: newItems };
        }
      }
      return r;
    }));
  };

  const getCategoryColor = (catName: string) => {
    return categories.find(c => c.name === catName)?.color || 'bg-gray-400';
  };

  const CompactExerciseRow = ({ exerciseId, onRemove }: { exerciseId: number, onRemove: () => void }) => {
    const ex = exercises.find(e => e.id === exerciseId);
    if (!ex) return null;

    return (
      <div className="group flex items-center gap-3 px-3 py-2 bg-white hover:bg-blue-50 border-b border-gray-100 last:border-0 transition-colors">
        <div className="flex-shrink-0">
          <GripVertical size={14} className="text-gray-300 group-hover:text-blue-400" />
        </div>
        <div className="flex-1 min-w-0 flex items-center gap-3 overflow-hidden">
          <span className="text-sm font-semibold text-gray-800 whitespace-nowrap">{ex.title}</span>
          <span className="text-gray-300">|</span>
          <span className={`px-1.5 py-0.5 rounded text-[10px] font-bold text-white uppercase tracking-wider whitespace-nowrap ${getCategoryColor(ex.category)}`}>
            {ex.category}
          </span>
          <span className="text-gray-300 hidden sm:inline">|</span>
          <span className="text-xs text-gray-500 truncate italic hidden sm:inline">
            {ex.description || 'No description provided'}
          </span>
        </div>
        <button 
          onClick={onRemove}
          className="p-1 opacity-0 group-hover:opacity-100 hover:bg-red-50 rounded text-red-400 hover:text-red-600 transition-all"
        >
          <Trash2 size={14} />
        </button>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center bg-white p-4 rounded-xl shadow-sm border border-gray-200">
        <div>
          <h2 className="text-xl font-bold text-gray-800">Routine Builder</h2>
          <p className="text-xs text-gray-500">Drag exercises from library to build your plan</p>
        </div>
        <button 
          onClick={createRoutine}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 shadow-md transition-all active:scale-95"
        >
          <Plus size={20} /> Create Routine
        </button>
      </div>

      <div className="grid gap-6">
        {routines.length === 0 ? (
          <div className="bg-white border-2 border-dashed border-gray-200 rounded-2xl py-20 text-center">
            <Layers size={48} className="mx-auto text-gray-200 mb-4" />
            <p className="text-gray-400 font-medium">No routines yet. Click above to start building!</p>
          </div>
        ) : (
          routines.map((routine) => (
            <div key={routine.id} className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden transition-all duration-300">
              {/* Routine Header */}
              <div className="flex items-center gap-3 p-4 bg-gray-50/50 border-b border-gray-100">
                <button 
                  onClick={() => updateRoutine(routine.id, { isExpanded: !routine.isExpanded })}
                  className="p-1 hover:bg-gray-200 rounded transition-colors text-gray-600"
                >
                  {routine.isExpanded ? <ChevronDown size={20} /> : <ChevronRight size={20} />}
                </button>
                <input 
                  type="text" 
                  value={routine.name} 
                  onChange={(e) => updateRoutine(routine.id, { name: e.target.value })}
                  className="bg-transparent font-bold text-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-blue-500 rounded px-2 flex-1"
                />
                <div className="flex items-center gap-2">
                  <span className="text-[10px] font-bold text-gray-400 bg-gray-100 px-2 py-1 rounded-full uppercase">
                    {routine.exerciseItems.length + routine.subRoutines.reduce((acc, sr) => acc + sr.exerciseItems.length, 0)} Items
                  </span>
                  <button 
                    onClick={() => addSection(routine.id)}
                    className="p-2 hover:bg-blue-50 text-blue-600 rounded-lg transition-colors"
                    title="Add Section"
                  >
                    <Plus size={18} />
                  </button>
                  <button 
                    onClick={() => deleteRoutine(routine.id)}
                    className="p-2 hover:bg-red-50 text-red-500 rounded-lg transition-colors"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>

              {/* Routine Content */}
              {routine.isExpanded && (
                <div className="p-4 space-y-4 animate-in slide-in-from-top-2 duration-200">
                  {/* Drop Zone for Main Exercises */}
                  <div 
                    onDragOver={e => e.preventDefault()}
                    onDrop={e => handleDrop(e, routine.id)}
                    className="border-2 border-dashed border-gray-100 rounded-xl bg-gray-50/50 overflow-hidden"
                  >
                    {routine.exerciseItems.length === 0 && routine.subRoutines.length === 0 && (
                      <p className="text-center py-6 text-sm text-gray-400">Drag items here or add a section</p>
                    )}
                    <div className="bg-white">
                      {routine.exerciseItems.map((item, idx) => (
                        <CompactExerciseRow 
                          key={`${item.exerciseId}-${idx}`} 
                          exerciseId={item.exerciseId} 
                          onRemove={() => removeExercise(routine.id, idx)} 
                        />
                      ))}
                    </div>
                  </div>

                  {/* Sub Routines / Sections */}
                  {routine.subRoutines.map((sr) => (
                    <div key={sr.id} className="bg-white border border-gray-100 rounded-xl shadow-sm overflow-hidden">
                      <div className="flex items-center gap-2 p-2 px-3 bg-blue-50/50 border-b border-blue-100">
                        <button 
                          onClick={() => {
                            const newSubRoutines = routine.subRoutines.map(s => s.id === sr.id ? {...s, isExpanded: !s.isExpanded} : s);
                            updateRoutine(routine.id, { subRoutines: newSubRoutines });
                          }}
                          className="text-blue-600"
                        >
                          {sr.isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                        </button>
                        <input 
                          type="text" 
                          value={sr.name} 
                          onChange={(e) => {
                            const newSubRoutines = routine.subRoutines.map(s => s.id === sr.id ? {...s, name: e.target.value} : s);
                            updateRoutine(routine.id, { subRoutines: newSubRoutines });
                          }}
                          className="bg-transparent text-sm font-bold text-blue-900 focus:outline-none flex-1"
                        />
                        <button 
                          onClick={() => {
                            const newSubRoutines = routine.subRoutines.filter(s => s.id !== sr.id);
                            updateRoutine(routine.id, { subRoutines: newSubRoutines });
                          }}
                          className="p-1 hover:bg-red-100 rounded text-red-400"
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>

                      {sr.isExpanded && (
                        <div 
                          onDragOver={e => e.preventDefault()}
                          onDrop={e => handleDrop(e, routine.id, sr.id)}
                          className="min-h-[40px] bg-white"
                        >
                          {sr.exerciseItems.length === 0 ? (
                            <p className="text-center py-4 text-[10px] text-gray-400 uppercase tracking-widest">Drop exercises here</p>
                          ) : (
                            sr.exerciseItems.map((item, idx) => (
                              <CompactExerciseRow 
                                key={`${item.exerciseId}-${idx}`} 
                                exerciseId={item.exerciseId} 
                                onRemove={() => removeExercise(routine.id, idx, sr.id)} 
                              />
                            ))
                          )}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default RoutineBuilder;

import React, { useState } from 'react';
import { Plus, Trash2, Tag } from 'lucide-react';
import { Category, Exercise } from '../types';
import { COLORS } from '../constants';

interface CategoryManagerProps {
  categories: Category[];
  setCategories: React.Dispatch<React.SetStateAction<Category[]>>;
  exercises: Exercise[];
}

const CategoryManager: React.FC<CategoryManagerProps> = ({ categories, setCategories, exercises }) => {
  const [showForm, setShowForm] = useState(false);
  const [newName, setNewName] = useState('');
  const [selectedColor, setSelectedColor] = useState(COLORS[0]);

  const handleAdd = () => {
    if (!newName.trim() || categories.find(c => c.name.toLowerCase() === newName.toLowerCase())) return;
    setCategories([...categories, { name: newName.trim(), color: selectedColor }]);
    setNewName('');
    setShowForm(false);
  };

  const handleDelete = (name: string) => {
    if (exercises.some(ex => ex.category === name)) {
      alert("Cannot delete category while it is in use by exercises.");
      return;
    }
    if (confirm(`Delete category "${name}"?`)) {
      setCategories(prev => prev.filter(c => c.name !== name));
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center bg-white p-6 rounded-2xl shadow-sm border border-gray-200">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Category Manager</h2>
          <p className="text-gray-500">Organize your exercise library with custom labels</p>
        </div>
        <button 
          onClick={() => setShowForm(true)}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg transition-all"
        >
          <Plus size={20} /> Add Category
        </button>
      </div>

      {showForm && (
        <div className="bg-white p-6 rounded-2xl border border-blue-200 shadow-xl space-y-4 animate-in zoom-in-95 duration-200">
          <div className="flex justify-between items-center">
            <h3 className="font-bold text-gray-800">New Category</h3>
            <button onClick={() => setShowForm(false)} className="text-gray-400 hover:text-gray-600"><Tag size={20} /></button>
          </div>

          <div className="grid gap-4 sm:grid-cols-2">
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">Label Name</label>
              <input 
                type="text" 
                value={newName}
                onChange={e => setNewName(e.target.value)}
                className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none"
                placeholder="e.g. Strength"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-2">Pick Color</label>
              <div className="flex flex-wrap gap-2">
                {COLORS.map(color => (
                  <button
                    key={color}
                    onClick={() => setSelectedColor(color)}
                    className={`w-8 h-8 rounded-full ${color} transition-transform ${selectedColor === color ? 'scale-125 ring-2 ring-offset-2 ring-gray-400' : 'hover:scale-110'}`}
                  />
                ))}
              </div>
            </div>
          </div>

          <div className="flex gap-2 pt-2">
            <button 
              onClick={handleAdd}
              className="flex-1 py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-md"
            >
              Save Category
            </button>
            <button 
              onClick={() => setShowForm(false)}
              className="px-6 py-3 bg-gray-100 text-gray-600 rounded-xl font-bold hover:bg-gray-200"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {categories.map(cat => (
          <div key={cat.name} className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm flex items-center justify-between group hover:shadow-md transition-shadow">
            <div className="flex items-center gap-3">
              <div className={`w-4 h-4 rounded-full ${cat.color}`} />
              <div className="min-w-0">
                <p className="font-bold text-gray-800 truncate">{cat.name}</p>
                <p className="text-[10px] text-gray-400 font-bold uppercase tracking-tighter">
                  {exercises.filter(e => e.category === cat.name).length} Exercises
                </p>
              </div>
            </div>
            <button 
              onClick={() => handleDelete(cat.name)}
              className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors opacity-0 group-hover:opacity-100"
            >
              <Trash2 size={18} />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default CategoryManager;

import React from 'react';
import { 
  Plus, 
  Trash2, 
  ChevronDown, 
  ChevronRight, 
  GripVertical,
  Layers
} from 'lucide-react';
import { Routine, Exercise, Category, SubRoutine, ExerciseItem } from '../types';

interface RoutineBuilderProps {
  routines: Routine[];
  setRoutines: React.Dispatch<React.SetStateAction<Routine[]>>;
  exercises: Exercise[];
  categories: Category[];
}

// Fix: Moved CompactExerciseRow outside the main component to resolve 'key' prop TypeScript errors 
// and prevent component re-definition on every render cycle of the parent.
const CompactExerciseRow: React.FC<{ 
  exerciseId: number; 
  onRemove: () => void; 
  exercises: Exercise[]; 
  categories: Category[]; 
}> = ({ exerciseId, onRemove, exercises, categories }) => {
  const ex = exercises.find(e => e.id === exerciseId);
  if (!ex) return null;

  const getCategoryColor = (catName: string) => {
    return categories.find(c => c.name === catName)?.color || 'bg-gray-400';
  };

  return (
    <div className="group flex items-center gap-3 px-3 py-2 bg-white hover:bg-blue-50 border-b border-gray-100 last:border-0 transition-colors">
      <div className="flex-shrink-0">
        <GripVertical size={14} className="text-gray-300 group-hover:text-blue-400" />
      </div>
      <div className="flex-1 min-w-0 flex items-center gap-3 overflow-hidden">
        <span className="text-sm font-semibold text-gray-800 whitespace-nowrap">{ex.title}</span>
        <span className="text-gray-300">|</span>
        <span className={`px-1.5 py-0.5 rounded text-[10px] font-bold text-white uppercase tracking-wider whitespace-nowrap ${getCategoryColor(ex.category)}`}>
          {ex.category}
        </span>
        <span className="text-gray-300 hidden sm:inline">|</span>
        <span className="text-xs text-gray-500 truncate italic hidden sm:inline">
          {ex.description || 'No description provided'}
        </span>
      </div>
      <button 
        onClick={onRemove}
        className="p-1 opacity-0 group-hover:opacity-100 hover:bg-red-50 rounded text-red-400 hover:text-red-600 transition-all"
      >
        <Trash2 size={14} />
      </button>
    </div>
  );
};

const RoutineBuilder: React.FC<RoutineBuilderProps> = ({ routines, setRoutines, exercises, categories }) => {

  const createRoutine = () => {
    const newRoutine: Routine = {
      id: Date.now(),
      name: 'New Routine',
      exerciseItems: [],
      subRoutines: [],
      isExpanded: true
    };
    setRoutines([newRoutine, ...routines]);
  };

  const updateRoutine = (id: number, updates: Partial<Routine>) => {
    setRoutines(prev => prev.map(r => r.id === id ? { ...r, ...updates } : r));
  };

  const deleteRoutine = (id: number) => {
    if (confirm("Delete this entire routine?")) {
      setRoutines(prev => prev.filter(r => r.id !== id));
    }
  };

  const addSection = (routineId: number) => {
    setRoutines(prev => prev.map(r => {
      if (r.id === routineId) {
        return {
          ...r,
          subRoutines: [...r.subRoutines, { id: Date.now(), name: 'New Section', exerciseItems: [], isExpanded: true }]
        };
      }
      return r;
    }));
  };

  const handleDrop = (e: React.DragEvent, routineId: number, subRoutineId?: number) => {
    e.preventDefault();
    const exerciseId = parseInt(e.dataTransfer.getData('exerciseId'));
    if (!exerciseId) return;

    setRoutines(prev => prev.map(r => {
      if (r.id === routineId) {
        if (subRoutineId) {
          return {
            ...r,
            subRoutines: r.subRoutines.map(sr => {
              if (sr.id === subRoutineId) {
                return { ...sr, exerciseItems: [...sr.exerciseItems, { exerciseId }] };
              }
              return sr;
            })
          };
        } else {
          return { ...r, exerciseItems: [...r.exerciseItems, { exerciseId }] };
        }
      }
      return r;
    }));
  };

  const removeExercise = (routineId: number, index: number, subRoutineId?: number) => {
    setRoutines(prev => prev.map(r => {
      if (r.id === routineId) {
        if (subRoutineId) {
          return {
            ...r,
            subRoutines: r.subRoutines.map(sr => {
              if (sr.id === subRoutineId) {
                const newItems = [...sr.exerciseItems];
                newItems.splice(index, 1);
                return { ...sr, exerciseItems: newItems };
              }
              return sr;
            })
          };
        } else {
          const newItems = [...r.exerciseItems];
          newItems.splice(index, 1);
          return { ...r, exerciseItems: newItems };
        }
      }
      return r;
    }));
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center bg-white p-4 rounded-xl shadow-sm border border-gray-200">
        <div>
          <h2 className="text-xl font-bold text-gray-800">Routine Builder</h2>
          <p className="text-xs text-gray-500">Drag exercises from library to build your plan</p>
        </div>
        <button 
          onClick={createRoutine}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 shadow-md transition-all active:scale-95"
        >
          <Plus size={20} /> Create Routine
        </button>
      </div>

      <div className="grid gap-6">
        {routines.length === 0 ? (
          <div className="bg-white border-2 border-dashed border-gray-200 rounded-2xl py-20 text-center">
            <Layers size={48} className="mx-auto text-gray-200 mb-4" />
            <p className="text-gray-400 font-medium">No routines yet. Click above to start building!</p>
          </div>
        ) : (
          routines.map((routine) => (
            <div key={routine.id} className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden transition-all duration-300">
              {/* Routine Header */}
              <div className="flex items-center gap-3 p-4 bg-gray-50/50 border-b border-gray-100">
                <button 
                  onClick={() => updateRoutine(routine.id, { isExpanded: !routine.isExpanded })}
                  className="p-1 hover:bg-gray-200 rounded transition-colors text-gray-600"
                >
                  {routine.isExpanded ? <ChevronDown size={20} /> : <ChevronRight size={20} />}
                </button>
                <input 
                  type="text" 
                  value={routine.name} 
                  onChange={(e) => updateRoutine(routine.id, { name: e.target.value })}
                  className="bg-transparent font-bold text-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-blue-500 rounded px-2 flex-1"
                />
                <div className="flex items-center gap-2">
                  <span className="text-[10px] font-bold text-gray-400 bg-gray-100 px-2 py-1 rounded-full uppercase">
                    {routine.exerciseItems.length + routine.subRoutines.reduce((acc, sr) => acc + sr.exerciseItems.length, 0)} Items
                  </span>
                  <button 
                    onClick={() => addSection(routine.id)}
                    className="p-2 hover:bg-blue-50 text-blue-600 rounded-lg transition-colors"
                    title="Add Section"
                  >
                    <Plus size={18} />
                  </button>
                  <button 
                    onClick={() => deleteRoutine(routine.id)}
                    className="p-2 hover:bg-red-50 text-red-500 rounded-lg transition-colors"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>

              {/* Routine Content */}
              {routine.isExpanded && (
                <div className="p-4 space-y-4 animate-in slide-in-from-top-2 duration-200">
                  {/* Drop Zone for Main Exercises */}
                  <div 
                    onDragOver={e => e.preventDefault()}
                    onDrop={e => handleDrop(e, routine.id)}
                    className="border-2 border-dashed border-gray-100 rounded-xl bg-gray-50/50 overflow-hidden"
                  >
                    {routine.exerciseItems.length === 0 && routine.subRoutines.length === 0 && (
                      <p className="text-center py-6 text-sm text-gray-400">Drag items here or add a section</p>
                    )}
                    <div className="bg-white">
                      {routine.exerciseItems.map((item, idx) => (
                        <CompactExerciseRow 
                          key={`${item.exerciseId}-${idx}`} 
                          exerciseId={item.exerciseId} 
                          onRemove={() => removeExercise(routine.id, idx)} 
                          exercises={exercises}
                          categories={categories}
                        />
                      ))}
                    </div>
                  </div>

                  {/* Sub Routines / Sections */}
                  {routine.subRoutines.map((sr) => (
                    <div key={sr.id} className="bg-white border border-gray-100 rounded-xl shadow-sm overflow-hidden">
                      <div className="flex items-center gap-2 p-2 px-3 bg-blue-50/50 border-b border-blue-100">
                        <button 
                          onClick={() => {
                            const newSubRoutines = routine.subRoutines.map(s => s.id === sr.id ? {...s, isExpanded: !s.isExpanded} : s);
                            updateRoutine(routine.id, { subRoutines: newSubRoutines });
                          }}
                          className="text-blue-600"
                        >
                          {sr.isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                        </button>
                        <input 
                          type="text" 
                          value={sr.name} 
                          onChange={(e) => {
                            const newSubRoutines = routine.subRoutines.map(s => s.id === sr.id ? {...s, name: e.target.value} : s);
                            updateRoutine(routine.id, { subRoutines: newSubRoutines });
                          }}
                          className="bg-transparent text-sm font-bold text-blue-900 focus:outline-none flex-1"
                        />
                        <button 
                          onClick={() => {
                            const newSubRoutines = routine.subRoutines.filter(s => s.id !== sr.id);
                            updateRoutine(routine.id, { subRoutines: newSubRoutines });
                          }}
                          className="p-1 hover:bg-red-100 rounded text-red-400"
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>

                      {sr.isExpanded && (
                        <div 
                          onDragOver={e => e.preventDefault()}
                          onDrop={e => handleDrop(e, routine.id, sr.id)}
                          className="min-h-[40px] bg-white"
                        >
                          {sr.exerciseItems.length === 0 ? (
                            <p className="text-center py-4 text-[10px] text-gray-400 uppercase tracking-widest">Drop exercises here</p>
                          ) : (
                            sr.exerciseItems.map((item, idx) => (
                              <CompactExerciseRow 
                                key={`${item.exerciseId}-${idx}`} 
                                exerciseId={item.exerciseId} 
                                onRemove={() => removeExercise(routine.id, idx, sr.id)} 
                                exercises={exercises}
                                categories={categories}
                              />
                            ))
                          )}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default RoutineBuilder;

export interface Exercise {
  id: number;
  title: string;
  description: string;
  category: string;
  videoUrl: string;
  rating: number;
}

export interface ExerciseItem {
  exerciseId: number;
}

export interface SubRoutine {
