            >
              <X size={24} />
            </button>
            <iframe
              src={activeVideoUrl}
              className="w-full h-full"
              frameBorder="0"
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
              allowFullScreen
            />
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { 
  Plus, 
  Edit2, 
  Trash2, 
  Search,
  X,
  Star,
  GripVertical,
  PlayCircle
} from 'lucide-react';
import { Exercise, Category } from '../types';

interface SidebarProps {
  exercises: Exercise[];
  setExercises: React.Dispatch<React.SetStateAction<Exercise[]>>;
  categories: Category[];
  onPlayVideo: (url: string) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ exercises, setExercises, categories, onPlayVideo }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);

  const [formData, setFormData] = useState<Partial<Exercise>>({
    title: '',
    description: '',
    category: categories[0]?.name || 'Mobility',
    videoUrl: '',
    rating: 0
  });

  const resetForm = () => {
    setFormData({
      title: '',
      description: '',
      category: categories[0]?.name || 'Mobility',
      videoUrl: '',
      rating: 0
    });
    setEditingId(null);
    setShowAddForm(false);
  };

  const handleSave = () => {
    if (!formData.title?.trim()) return;

    if (editingId) {
      setExercises(prev => prev.map(ex => ex.id === editingId ? { ...ex, ...formData } as Exercise : ex));
    } else {
      const newEx: Exercise = {
        id: Date.now(),
        title: formData.title || '',
        description: formData.description || '',
        category: formData.category || categories[0]?.name || 'Mobility',
        videoUrl: formData.videoUrl || '',
        rating: formData.rating || 0,
      };
      setExercises(prev => [...prev, newEx]);
    }
    resetForm();
  };

  const handleEdit = (ex: Exercise) => {
    setEditingId(ex.id);
    setFormData({ ...ex });
    setShowAddForm(true);
  };

  const handleDelete = (id: number) => {
    if (confirm("Delete this exercise from library?")) {
      setExercises(prev => prev.filter(e => e.id !== id));
    }
  };

  const filteredExercises = exercises.filter(ex => 
    ex.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    ex.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const grouped = categories.map(cat => ({
    category: cat,
    items: filteredExercises.filter(ex => ex.category === cat.name)
  })).filter(g => g.items.length > 0);

  const StarRating = ({ rating, onRate }: { rating: number; onRate: (r: number) => void }) => (
    <div className="flex gap-1">
      {[1, 2, 3, 4, 5].map(star => (
        <button
          key={star}
          onClick={() => onRate(star)}
          className={`transition-colors ${rating >= star ? 'text-yellow-400' : 'text-gray-300'}`}
        >
          <Star size={16} fill={rating >= star ? 'currentColor' : 'none'} />
        </button>
      ))}
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-white border-r border-gray-100">
      <div className="p-5 border-b border-gray-50 bg-gray-50/30">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-lg font-bold text-gray-800">Exercise Library</h2>
          <button 
            onClick={() => setShowAddForm(true)}
            className="flex items-center gap-1 px-3 py-1.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-all shadow-sm text-sm"
          >
            <Plus size={16} /> <span>New</span>
          </button>
        </div>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
          <input 
            type="text" 
            placeholder="Filter library..." 
            className="w-full pl-10 pr-4 py-2 bg-white border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 shadow-sm"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        {showAddForm && (
          <div className="p-4 bg-gray-50 rounded-xl border border-gray-200 shadow-sm space-y-4 relative animate-in fade-in slide-in-from-top-2 duration-200">
            <button onClick={resetForm} className="absolute top-2 right-2 text-gray-400 hover:text-gray-600">
              <X size={16} />
            </button>
            <h3 className="font-bold text-gray-800 text-sm">{editingId ? 'Update Exercise' : 'Create Exercise'}</h3>

            <div className="space-y-3">
              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Title</label>
                <input 
                  type="text" 
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500"
                  value={formData.title}
                  onChange={e => setFormData({...formData, title: e.target.value})}
                  placeholder="e.g. Chin Tuck Hold"
                />
              </div>

              <div className="flex gap-3">
                <div className="flex-1">
                  <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Category</label>
                  <select 
                    className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500"
                    value={formData.category}
                    onChange={e => setFormData({...formData, category: e.target.value})}
                  >
                    {categories.map(c => <option key={c.name} value={c.name}>{c.name}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Rating</label>
                  <StarRating rating={formData.rating || 0} onRate={r => setFormData({...formData, rating: r})} />
                </div>
              </div>

              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Description</label>
                <textarea 
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500"
                  rows={2}
                  value={formData.description}
                  onChange={e => setFormData({...formData, description: e.target.value})}
                  placeholder="Instructions for the exercise..."
                />
              </div>

              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Video Link (YouTube)</label>
                <input 
                  type="text" 
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500"
                  value={formData.videoUrl}
                  onChange={e => setFormData({...formData, videoUrl: e.target.value})}
                  placeholder="Paste URL to enable in-app player"
                />
              </div>
            </div>

            <div className="flex gap-2 pt-2">
              <button 
                onClick={handleSave}
                className="flex-1 py-2 bg-blue-600 text-white rounded-lg text-sm font-semibold hover:bg-blue-700 shadow-sm"
              >
                {editingId ? 'Save Changes' : 'Add to Library'}
              </button>
            </div>
          </div>
        )}

        {grouped.length === 0 ? (
          <div className="text-center py-10">
            <p className="text-gray-400 text-sm">No exercises found.</p>
          </div>
        ) : (
          grouped.map(({ category, items }) => (
            <div key={category.name} className="space-y-2">
              <div className="flex items-center gap-2 px-1">
                <div className={`w-2 h-2 rounded-full ${category.color}`} />
                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest">{category.name}</h4>
              </div>
              <div className="space-y-1.5">
                {items.map(ex => (
                  <div 
                    key={ex.id}
                    draggable
                    onDragStart={(e) => {
                      e.dataTransfer.setData('exerciseId', ex.id.toString());
                    }}
                    className="group flex items-center gap-2 p-3 bg-white border border-gray-100 rounded-xl hover:border-blue-200 hover:shadow-md transition-all cursor-grab active:cursor-grabbing"
                  >
                    <GripVertical size={16} className="text-gray-300 group-hover:text-blue-400 transition-colors" />
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-1.5">
                        <p className="text-sm font-semibold text-gray-700 truncate">{ex.title}</p>
                        {ex.videoUrl && (
                          <button 
                            onClick={(e) => { e.stopPropagation(); onPlayVideo(ex.videoUrl); }}
                            className="text-blue-500 hover:text-blue-700 transition-colors"
                          >
                            <PlayCircle size={14} />
                          </button>
                        )}
                      </div>
                      {ex.rating > 0 && (
                        <div className="flex items-center gap-0.5 mt-0.5">
                          {[...Array(ex.rating)].map((_, i) => (
                            <div key={i} className="w-1.5 h-1.5 rounded-full bg-yellow-400" />
                          ))}
                        </div>
                      )}
                    </div>
                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button 
                        onClick={() => handleEdit(ex)}
                        className="p-1.5 hover:bg-gray-100 rounded-lg text-gray-400 hover:text-blue-500"
                      >
                        <Edit2 size={14} />
                      </button>
                      <button 
                        onClick={() => handleDelete(ex.id)}
                        className="p-1.5 hover:bg-red-50 rounded-lg text-gray-400 hover:text-red-500"
                      >
                        <Trash2 size={14} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default Sidebar;

import React from 'react';
import { 
  Plus, 
  Trash2, 
  ChevronDown, 
  ChevronRight, 
  GripVertical,
  Layers,
  PlayCircle
} from 'lucide-react';
import { Routine, Exercise, Category, SubRoutine, ExerciseItem } from '../types';

interface RoutineBuilderProps {
  routines: Routine[];
  setRoutines: React.Dispatch<React.SetStateAction<Routine[]>>;
  exercises: Exercise[];
  categories: Category[];
  onPlayVideo: (url: string) => void;
}

const CompactExerciseRow: React.FC<{ 
  exerciseId: number; 
  onRemove: () => void; 
  exercises: Exercise[]; 
  categories: Category[];
  onPlayVideo: (url: string) => void;
}> = ({ exerciseId, onRemove, exercises, categories, onPlayVideo }) => {
  const ex = exercises.find(e => e.id === exerciseId);
  if (!ex) return null;

  const getCategoryColor = (catName: string) => {
    return categories.find(c => c.name === catName)?.color || 'bg-gray-400';
  };

  const hasVideo = !!ex.videoUrl;

  return (
    <div 
      onClick={() => hasVideo && onPlayVideo(ex.videoUrl)}
      className={`group flex items-center gap-3 px-3 py-2 bg-white hover:bg-blue-50 border-b border-gray-100 last:border-0 transition-colors ${hasVideo ? 'cursor-pointer' : ''}`}
    >
      <div className="flex-shrink-0">
        <GripVertical size={14} className="text-gray-300 group-hover:text-blue-400" />
      </div>
      <div className="flex-1 min-w-0 flex items-center gap-3 overflow-hidden">
        <div className="flex items-center gap-2 overflow-hidden">
          <span className="text-sm font-semibold text-gray-800 whitespace-nowrap">{ex.title}</span>
          {hasVideo && <PlayCircle size={14} className="text-blue-500 flex-shrink-0" />}
        </div>
        <span className="text-gray-300">|</span>
        <span className={`px-1.5 py-0.5 rounded text-[10px] font-bold text-white uppercase tracking-wider whitespace-nowrap ${getCategoryColor(ex.category)}`}>
          {ex.category}
        </span>
        <span className="text-gray-300 hidden sm:inline">|</span>
        <span className="text-xs text-gray-500 truncate italic hidden sm:inline">
          {ex.description || 'No description provided'}
        </span>
      </div>
      <button 
        onClick={(e) => { e.stopPropagation(); onRemove(); }}
        className="p-1 opacity-0 group-hover:opacity-100 hover:bg-red-50 rounded text-red-400 hover:text-red-600 transition-all"
      >
        <Trash2 size={14} />
      </button>
    </div>
  );
};

const RoutineBuilder: React.FC<RoutineBuilderProps> = ({ routines, setRoutines, exercises, categories, onPlayVideo }) => {

  const createRoutine = () => {
    const newRoutine: Routine = {
      id: Date.now(),
      name: 'New Routine',
      exerciseItems: [],
      subRoutines: [],
      isExpanded: true
    };
    setRoutines([newRoutine, ...routines]);
  };

  const updateRoutine = (id: number, updates: Partial<Routine>) => {
    setRoutines(prev => prev.map(r => r.id === id ? { ...r, ...updates } : r));
  };

  const deleteRoutine = (id: number) => {
    if (confirm("Delete this entire routine?")) {
      setRoutines(prev => prev.filter(r => r.id !== id));
    }
  };

  const addSection = (routineId: number) => {
    setRoutines(prev => prev.map(r => {
      if (r.id === routineId) {
        return {
          ...r,
          subRoutines: [...r.subRoutines, { id: Date.now(), name: 'New Section', exerciseItems: [], isExpanded: true }]
        };
      }
      return r;
    }));
  };

  const handleDrop = (e: React.DragEvent, routineId: number, subRoutineId?: number) => {
    e.preventDefault();
    const exerciseId = parseInt(e.dataTransfer.getData('exerciseId'));
    if (!exerciseId) return;

    setRoutines(prev => prev.map(r => {
      if (r.id === routineId) {
        if (subRoutineId) {
          return {
            ...r,
            subRoutines: r.subRoutines.map(sr => {
              if (sr.id === subRoutineId) {
                return { ...sr, exerciseItems: [...sr.exerciseItems, { exerciseId }] };
              }
              return sr;
            })
          };
        } else {
          return { ...r, exerciseItems: [...r.exerciseItems, { exerciseId }] };
        }
      }
      return r;
    }));
  };

  const removeExercise = (routineId: number, index: number, subRoutineId?: number) => {
    setRoutines(prev => prev.map(r => {
      if (r.id === routineId) {
        if (subRoutineId) {
          return {
            ...r,
            subRoutines: r.subRoutines.map(sr => {
              if (sr.id === subRoutineId) {
                const newItems = [...sr.exerciseItems];
                newItems.splice(index, 1);
                return { ...sr, exerciseItems: newItems };
              }
              return sr;
            })
          };
        } else {
          const newItems = [...r.exerciseItems];
          newItems.splice(index, 1);
          return { ...r, exerciseItems: newItems };
        }
      }
      return r;
    }));
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center bg-white p-4 rounded-xl shadow-sm border border-gray-200">
        <div>
          <h2 className="text-xl font-bold text-gray-800">Routine Builder</h2>
          <p className="text-xs text-gray-500">Manage routines and exercises efficiently</p>
        </div>
        <button 
          onClick={createRoutine}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 shadow-md transition-all active:scale-95"
        >
          <Plus size={20} /> Create Routine
        </button>
      </div>

      <div className="grid gap-6">
        {routines.length === 0 ? (
          <div className="bg-white border-2 border-dashed border-gray-200 rounded-2xl py-20 text-center">
            <Layers size={48} className="mx-auto text-gray-200 mb-4" />
            <p className="text-gray-400 font-medium">No routines yet. Create one to get started!</p>
          </div>
        ) : (
          routines.map((routine) => (
            <div key={routine.id} className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden transition-all duration-300">
              {/* Routine Header */}
              <div className="flex items-center gap-3 p-4 bg-gray-50/50 border-b border-gray-100">
                <button 
                  onClick={() => updateRoutine(routine.id, { isExpanded: !routine.isExpanded })}
                  className="p-1 hover:bg-gray-200 rounded transition-colors text-gray-600"
                >
                  {routine.isExpanded ? <ChevronDown size={20} /> : <ChevronRight size={20} />}
                </button>
                <input 
                  type="text" 
                  value={routine.name} 
                  onChange={(e) => updateRoutine(routine.id, { name: e.target.value })}
                  className="bg-transparent font-bold text-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-blue-500 rounded px-2 flex-1"
                />
                <div className="flex items-center gap-2">
                  <span className="text-[10px] font-bold text-gray-400 bg-gray-100 px-2 py-1 rounded-full uppercase">
                    {routine.exerciseItems.length + routine.subRoutines.reduce((acc, sr) => acc + sr.exerciseItems.length, 0)} Items
                  </span>
                  <button 
                    onClick={() => addSection(routine.id)}
                    className="p-2 hover:bg-blue-50 text-blue-600 rounded-lg transition-colors"
                    title="Add Section"
                  >
                    <Plus size={18} />
                  </button>
                  <button 
                    onClick={() => deleteRoutine(routine.id)}
                    className="p-2 hover:bg-red-50 text-red-500 rounded-lg transition-colors"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>

              {/* Routine Content */}
              {routine.isExpanded && (
                <div className="p-4 space-y-4 animate-in slide-in-from-top-2 duration-200">
                  {/* Drop Zone for Main Exercises */}
                  <div 
                    onDragOver={e => e.preventDefault()}
                    onDrop={e => handleDrop(e, routine.id)}
                    className="border-2 border-dashed border-gray-100 rounded-xl bg-gray-50/50 overflow-hidden"
                  >
                    {routine.exerciseItems.length === 0 && routine.subRoutines.length === 0 && (
                      <p className="text-center py-6 text-sm text-gray-400">Drag items here or add a section</p>
                    )}
                    <div className="bg-white">
                      {routine.exerciseItems.map((item, idx) => (
                        <CompactExerciseRow 
                          key={`${item.exerciseId}-${idx}`} 
                          exerciseId={item.exerciseId} 
                          onRemove={() => removeExercise(routine.id, idx)} 
                          exercises={exercises}
                          categories={categories}
                          onPlayVideo={onPlayVideo}
                        />
                      ))}
                    </div>
                  </div>

                  {/* Sub Routines / Sections */}
                  {routine.subRoutines.map((sr) => (
                    <div key={sr.id} className="bg-white border border-gray-100 rounded-xl shadow-sm overflow-hidden">
                      <div className="flex items-center gap-2 p-2 px-3 bg-blue-50/50 border-b border-blue-100">
                        <button 
                          onClick={() => {
                            const newSubRoutines = routine.subRoutines.map(s => s.id === sr.id ? {...s, isExpanded: !s.isExpanded} : s);
                            updateRoutine(routine.id, { subRoutines: newSubRoutines });
                          }}
                          className="text-blue-600"
                        >
                          {sr.isExpanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                        </button>
                        <input 
                          type="text" 
                          value={sr.name} 
                          onChange={(e) => {
                            const newSubRoutines = routine.subRoutines.map(s => s.id === sr.id ? {...s, name: e.target.value} : s);
                            updateRoutine(routine.id, { subRoutines: newSubRoutines });
                          }}
                          className="bg-transparent text-sm font-bold text-blue-900 focus:outline-none flex-1"
                        />
                        <button 
                          onClick={() => {
                            const newSubRoutines = routine.subRoutines.filter(s => s.id !== sr.id);
                            updateRoutine(routine.id, { subRoutines: newSubRoutines });
                          }}
                          className="p-1 hover:bg-red-100 rounded text-red-400"
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>

                      {sr.isExpanded && (
                        <div 
                          onDragOver={e => e.preventDefault()}
                          onDrop={e => handleDrop(e, routine.id, sr.id)}
                          className="min-h-[40px] bg-white"
                        >
                          {sr.exerciseItems.length === 0 ? (
                            <p className="text-center py-4 text-[10px] text-gray-400 uppercase tracking-widest">Drop exercises here</p>
                          ) : (
                            sr.exerciseItems.map((item, idx) => (
                              <CompactExerciseRow 
                                key={`${item.exerciseId}-${idx}`} 
                                exerciseId={item.exerciseId} 
                                onRemove={() => removeExercise(routine.id, idx, sr.id)} 
                                exercises={exercises}
                                categories={categories}
                                onPlayVideo={onPlayVideo}
                              />
                            ))
                          )}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default RoutineBuilder;

import React, { useState } from 'react';
import { 
  Plus, 
  Search, 
  ChevronDown, 
  ChevronRight, 
  Edit2, 
  Trash2, 
  Star,
  PlayCircle,
  X
} from 'lucide-react';
import { Exercise, Category } from '../types';

interface ExerciseLibraryProps {
  exercises: Exercise[];
  setExercises: React.Dispatch<React.SetStateAction<Exercise[]>>;
  categories: Category[];
  onPlayVideo: (url: string) => void;
}

const ExerciseLibrary: React.FC<ExerciseLibraryProps> = ({ exercises, setExercises, categories, onPlayVideo }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [collapsedCategories, setCollapsedCategories] = useState<Set<string>>(new Set());
  const [editingEx, setEditingEx] = useState<Exercise | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);

  const toggleCategory = (catName: string) => {
    const newCollapsed = new Set(collapsedCategories);
    if (newCollapsed.has(catName)) {
      newCollapsed.delete(catName);
    } else {
      newCollapsed.add(catName);
    }
    setCollapsedCategories(newCollapsed);
  };

  const handleDelete = (id: number) => {
    if (confirm("Permanently delete this exercise?")) {
      setExercises(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleEdit = (ex: Exercise) => {
    setEditingEx(ex);
    setShowAddForm(true);
  };

  const filteredExercises = exercises.filter(ex => 
    ex.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    ex.category.toLowerCase().includes(searchTerm.toLowerCase()) ||
    ex.description.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const groups = categories.map(cat => ({
    category: cat,
    items: filteredExercises.filter(ex => ex.category === cat.name)
  })).filter(g => g.items.length > 0 || searchTerm === '');

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-2xl border border-gray-200 shadow-sm">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Master Exercise Library</h2>
          <p className="text-gray-500">View and manage your entire exercise catalog</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Search exercises..." 
              className="pl-10 pr-4 py-2 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none w-full md:w-64"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={() => { setEditingEx(null); setShowAddForm(true); }}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-md transition-all whitespace-nowrap"
          >
            <Plus size={20} /> Add New
          </button>
        </div>
      </div>

      {showAddForm && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-gray-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between p-6 border-b">
              <h3 className="text-xl font-bold text-gray-800">{editingEx ? 'Edit Exercise' : 'Create Exercise'}</h3>
              <button onClick={() => setShowAddForm(false)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
            </div>
            <div className="p-6 space-y-4">
              <ExerciseForm 
                initialData={editingEx || undefined} 
                categories={categories} 
                onSave={(data) => {
                  if (editingEx) {
                    setExercises(prev => prev.map(ex => ex.id === editingEx.id ? { ...ex, ...data } as Exercise : ex));
                  } else {
                    setExercises(prev => [...prev, { ...data, id: Date.now() } as Exercise]);
                  }
                  setShowAddForm(false);
                }}
                onCancel={() => setShowAddForm(false)}
              />
            </div>
          </div>
        </div>
      )}

      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3 items-start">
        {groups.map(({ category, items }) => (
          <div 
            key={category.name} 
            className="bg-white rounded-2xl border border-gray-200 shadow-sm flex flex-col overflow-hidden"
          >
            {/* Folder Header */}
            <div 
              className={`h-2 w-full ${category.color}`}
            />
            <button 
              onClick={() => toggleCategory(category.name)}
              className="flex items-center justify-between p-4 bg-gray-50/50 hover:bg-gray-100 transition-colors"
            >
              <div className="flex items-center gap-3">
                <span className={`w-3 h-3 rounded-full ${category.color}`} />
                <h3 className="font-bold text-gray-700">{category.name}</h3>
                <span className="text-xs font-bold text-gray-400 bg-gray-200/50 px-2 py-0.5 rounded-full">{items.length}</span>
              </div>
              {collapsedCategories.has(category.name) ? <ChevronRight size={18} className="text-gray-400" /> : <ChevronDown size={18} className="text-gray-400" />}
            </button>

            {/* Folder Content */}
            {!collapsedCategories.has(category.name) && (
              <div className="p-3 space-y-3 min-h-[50px] bg-white animate-in slide-in-from-top-2 duration-200">
                {items.length === 0 ? (
                  <p className="text-center py-6 text-xs text-gray-400 italic">No matching exercises</p>
                ) : (
                  items.map(ex => (
                    <div 
                      key={ex.id} 
                      onClick={() => ex.videoUrl && onPlayVideo(ex.videoUrl)}
                      className={`group p-4 bg-gray-50 rounded-xl border border-transparent hover:border-blue-200 hover:bg-blue-50/30 transition-all ${ex.videoUrl ? 'cursor-pointer' : ''}`}
                    >
                      <div className="flex items-start justify-between gap-2 mb-2">
                        <div className="flex items-center gap-2">
                          <h4 className="font-bold text-gray-800 text-sm">{ex.title}</h4>
                          {ex.videoUrl && <PlayCircle size={14} className="text-blue-500" />}
                        </div>
                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={(e) => { e.stopPropagation(); handleEdit(ex); }} className="p-1 text-gray-400 hover:text-blue-600"><Edit2 size={14} /></button>
                          <button onClick={(e) => { e.stopPropagation(); handleDelete(ex.id); }} className="p-1 text-gray-400 hover:text-red-500"><Trash2 size={14} /></button>
                        </div>
                      </div>
                      <p className="text-xs text-gray-500 line-clamp-2 mb-3 leading-relaxed">
                        {ex.description || 'No description provided.'}
                      </p>
                      <div className="flex items-center justify-between">
                        <div className="flex gap-0.5">
                          {[...Array(5)].map((_, i) => (
                            <Star 
                              key={i} 
                              size={10} 
                              fill={i < ex.rating ? 'currentColor' : 'none'} 
                              className={i < ex.rating ? 'text-yellow-400' : 'text-gray-200'} 
                            />
                          ))}
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

const ExerciseForm: React.FC<{ 
