import React, { useState, useEffect } from 'react';
import { 
  Tag, 
  LayoutDashboard,
  BookOpen,
  ChevronLeft,
  Library,
  X
} from 'lucide-react';
import { Exercise, Routine, Category, ViewType } from './types';
import { DEFAULT_CATEGORIES } from './constants';
import Sidebar from './components/Sidebar';
import RoutineBuilder from './components/RoutineBuilder';
import CategoryManager from './components/CategoryManager';
import ExerciseLibrary from './components/ExerciseLibrary';

export default function App() {
  const [view, setView] = useState<ViewType>('main');
  const [exercises, setExercises] = useState<Exercise[]>([]);
  const [routines, setRoutines] = useState<Routine[]>([]);
  const [categories, setCategories] = useState<Category[]>(DEFAULT_CATEGORIES);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  // Fix for ExerciseLibrary required prop: state to track currently playing video
  const [activeVideoUrl, setActiveVideoUrl] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    try {
      const savedExercises = localStorage.getItem('exercises_v4');
      const savedRoutines = localStorage.getItem('routines_v4');
      const savedCategories = localStorage.getItem('categories_v4');

      if (savedExercises) setExercises(JSON.parse(savedExercises));
      if (savedRoutines) setRoutines(JSON.parse(savedRoutines));
      if (savedCategories) setCategories(JSON.parse(savedCategories));
    } catch (e) {
      console.error("Failed to load data", e);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('exercises_v4', JSON.stringify(exercises));
    localStorage.setItem('routines_v4', JSON.stringify(routines));
    localStorage.setItem('categories_v4', JSON.stringify(categories));
  }, [exercises, routines, categories]);

  const handleToggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  // Helper to get YouTube embed URL for the global modal
  const getYoutubeEmbedUrl = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    const id = (match && match[2].length === 11) ? match[2] : null;
    if (!id) return null;
    const origin = window.location.origin;
    return `https://www.youtube.com/embed/${id}?rel=0&modestbranding=1&origin=${encodeURIComponent(origin)}&enablejsapi=1`;
  };

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-50 text-gray-900 font-sans">
      {/* Header */}
      <header className="bg-white border-b px-6 py-3 flex items-center justify-between flex-shrink-0 z-30 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white shadow-sm">
              <LayoutDashboard size={18} />
            </div>
            <h1 className="text-xl font-bold text-gray-800 tracking-tight hidden sm:block">Routine Builder</h1>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => setView('main')}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
              view === 'main' 
                ? 'bg-blue-600 text-white shadow-md' 
                : 'bg-white text-gray-600 hover:bg-gray-100 border border-gray-200'
            }`}
          >
            <LayoutDashboard size={16} /> <span className="hidden md:inline">Builder</span>
          </button>
          <button
            onClick={() => setView('exercises')}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
              view === 'exercises' 
                ? 'bg-blue-600 text-white shadow-md' 
                : 'bg-white text-gray-600 hover:bg-gray-100 border border-gray-200'
            }`}
          >
            <BookOpen size={16} /> <span className="hidden md:inline">Exercise Library</span>
          </button>
          <button
            onClick={() => setView('categories')}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
              view === 'categories' 
                ? 'bg-blue-600 text-white shadow-md' 
                : 'bg-white text-gray-600 hover:bg-gray-100 border border-gray-200'
            }`}
          >
            <Tag size={16} /> <span className="hidden md:inline">Categories</span>
          </button>
        </div>
      </header>

      <main className="flex flex-1 overflow-hidden relative">
        {view === 'main' ? (
          <>
            {/* RETRACTABLE AREA WRAPPER */}
            <div 
              className={`flex h-full relative z-20 transition-all duration-300 ease-in-out ${
                isSidebarOpen ? 'w-1/3 min-w-[340px]' : 'w-10 bg-white border-r border-gray-200'
              }`}
            >
              {/* SIDEBAR CONTENT */}
              <aside className={`h-full w-full bg-white transition-opacity duration-300 ${isSidebarOpen ? 'opacity-100 border-r border-gray-200' : 'opacity-0 pointer-events-none'}`}>
                <div className="w-full h-full min-w-[340px]">
                  <Sidebar 
                    exercises={exercises} 
                    setExercises={setExercises} 
                    categories={categories}
                  />
                </div>
              </aside>

              {/* FLOATING TOGGLE BUTTON */}
              <div 
                className={`absolute top-4 z-50 transition-all duration-300 ${
                  isSidebarOpen ? '-right-4' : 'left-1'
                }`}
              >
                <button 
                  onClick={handleToggleSidebar}
                  className="flex items-center justify-center w-8 h-8 rounded-lg border border-gray-200 bg-white shadow-md text-gray-400 hover:text-blue-600 hover:bg-blue-50 transition-all active:scale-95"
                  title={isSidebarOpen ? "Collapse Library" : "Expand Library"}
                >
                  {isSidebarOpen ? <ChevronLeft size={20} /> : <Library size={18} />}
                </button>
              </div>

              {!isSidebarOpen && (
                <div 
                  onClick={handleToggleSidebar}
                  className="absolute inset-0 flex flex-col items-center pt-16 cursor-pointer hover:bg-blue-50/50 transition-colors"
                >
                  <div className="flex-1 w-[1px] bg-gray-100 mb-6" />
                  <div className="pb-8 opacity-20 select-none">
                    <p className="text-[9px] font-black tracking-[0.3em] text-gray-900 uppercase rotate-90 origin-center whitespace-nowrap">
                      LIBRARY
                    </p>
                  </div>
                </div>
              )}
            </div>

            {/* MAIN CONTENT AREA */}
            <div className="flex-1 overflow-y-auto p-4 sm:p-6 bg-gray-50">
              <div className="max-w-5xl mx-auto">
                <RoutineBuilder 
                  routines={routines} 
                  setRoutines={setRoutines} 
                  exercises={exercises}
                  categories={categories}
                />
              </div>
            </div>
          </>
        ) : view === 'exercises' ? (
          <div className="flex-1 overflow-y-auto p-4 sm:p-6 bg-gray-50">
            <div className="max-w-7xl mx-auto">
              <ExerciseLibrary 
                exercises={exercises}
                setExercises={setExercises}
                categories={categories}
                onPlayVideo={(url) => setActiveVideoUrl(url)}
              />
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-6">
            <div className="max-w-4xl mx-auto">
              <CategoryManager 
                categories={categories} 
                setCategories={setCategories} 
                exercises={exercises}
              />
            </div>
          </div>
        )}
      </main>

      {/* Global Video Modal for Exercise Library View */}
      {activeVideoUrl && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl overflow-hidden relative aspect-video">
             <button 
               onClick={() => setActiveVideoUrl(null)}
               className="absolute top-4 right-4 z-20 p-2 bg-black/50 hover:bg-black/80 text-white rounded-full transition-colors shadow-lg"
               title="Close video"
             >
               <X size={20} />
             </button>
             <iframe
               src={getYoutubeEmbedUrl(activeVideoUrl) || ''}
               className="w-full h-full"
               frameBorder="0"
               allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
               allowFullScreen
             />
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { 
  Plus, 
  Search, 
  ChevronDown, 
  ChevronRight, 
  Edit2, 
  Trash2, 
  Star,
  PlayCircle,
  X
} from 'lucide-react';
import { Exercise, Category } from '../types';

interface ExerciseLibraryProps {
  exercises: Exercise[];
  setExercises: React.Dispatch<React.SetStateAction<Exercise[]>>;
  categories: Category[];
  onPlayVideo: (url: string) => void;
}

const ExerciseLibrary: React.FC<ExerciseLibraryProps> = ({ exercises, setExercises, categories, onPlayVideo }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [collapsedCategories, setCollapsedCategories] = useState<Set<string>>(new Set());
  const [editingEx, setEditingEx] = useState<Exercise | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);

  const toggleCategory = (catName: string) => {
    const newCollapsed = new Set(collapsedCategories);
    if (newCollapsed.has(catName)) {
      newCollapsed.delete(catName);
    } else {
      newCollapsed.add(catName);
    }
    setCollapsedCategories(newCollapsed);
  };

  const handleDelete = (id: number) => {
    if (confirm("Permanently delete this exercise?")) {
      setExercises(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleEdit = (ex: Exercise) => {
    setEditingEx(ex);
    setShowAddForm(true);
  };

  const filteredExercises = exercises.filter(ex => 
    ex.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    ex.category.toLowerCase().includes(searchTerm.toLowerCase()) ||
    ex.description.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const groups = categories.map(cat => ({
    category: cat,
    items: filteredExercises.filter(ex => ex.category === cat.name)
  })).filter(g => g.items.length > 0 || searchTerm === '');

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-2xl border border-gray-200 shadow-sm">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Exercise Library</h2>
          <p className="text-gray-500">View and manage your entire exercise catalog</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Search exercises..." 
              className="pl-10 pr-4 py-2 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none w-full md:w-64"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={() => { setEditingEx(null); setShowAddForm(true); }}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-md transition-all whitespace-nowrap"
          >
            <Plus size={20} /> Add New
          </button>
        </div>
      </div>

      {showAddForm && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-gray-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between p-6 border-b">
              <h3 className="text-xl font-bold text-gray-800">{editingEx ? 'Edit Exercise' : 'Create Exercise'}</h3>
              <button onClick={() => setShowAddForm(false)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
            </div>
            <div className="p-6 space-y-4">
              <ExerciseForm 
                initialData={editingEx || undefined} 
                categories={categories} 
                onSave={(data) => {
                  if (editingEx) {
                    setExercises(prev => prev.map(ex => ex.id === editingEx.id ? { ...ex, ...data } as Exercise : ex));
                  } else {
                    setExercises(prev => [...prev, { ...data, id: Date.now() } as Exercise]);
                  }
                  setShowAddForm(false);
                }}
                onCancel={() => setShowAddForm(false)}
              />
            </div>
          </div>
        </div>
      )}

      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3 items-start">
        {groups.map(({ category, items }) => (
          <div 
            key={category.name} 
            className="bg-white rounded-2xl border border-gray-200 shadow-sm flex flex-col overflow-hidden"
          >
            {/* Folder Header */}
            <div 
              className={`h-2 w-full ${category.color}`}
            />
            <button 
              onClick={() => toggleCategory(category.name)}
              className="flex items-center justify-between p-4 bg-gray-50/50 hover:bg-gray-100 transition-colors"
            >
              <div className="flex items-center gap-3">
                <span className={`w-3 h-3 rounded-full ${category.color}`} />
                <h3 className="font-bold text-gray-700">{category.name}</h3>
                <span className="text-xs font-bold text-gray-400 bg-gray-200/50 px-2 py-0.5 rounded-full">{items.length}</span>
              </div>
              {collapsedCategories.has(category.name) ? <ChevronRight size={18} className="text-gray-400" /> : <ChevronDown size={18} className="text-gray-400" />}
            </button>

            {/* Folder Content */}
            {!collapsedCategories.has(category.name) && (
              <div className="p-3 space-y-3 min-h-[50px] bg-white animate-in slide-in-from-top-2 duration-200">
                {items.length === 0 ? (
                  <p className="text-center py-6 text-xs text-gray-400 italic">No matching exercises</p>
                ) : (
                  items.map(ex => (
                    <div 
                      key={ex.id} 
                      onClick={() => ex.videoUrl && onPlayVideo(ex.videoUrl)}
                      className={`group p-4 bg-gray-50 rounded-xl border border-transparent hover:border-blue-200 hover:bg-blue-50/30 transition-all ${ex.videoUrl ? 'cursor-pointer' : ''}`}
                    >
                      <div className="flex items-start justify-between gap-2 mb-2">
                        <div className="flex items-center gap-2">
                          <h4 className="font-bold text-gray-800 text-sm">{ex.title}</h4>
                          {ex.videoUrl && <PlayCircle size={14} className="text-blue-500" />}
                        </div>
                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={(e) => { e.stopPropagation(); handleEdit(ex); }} className="p-1 text-gray-400 hover:text-blue-600"><Edit2 size={14} /></button>
                          <button onClick={(e) => { e.stopPropagation(); handleDelete(ex.id); }} className="p-1 text-gray-400 hover:text-red-500"><Trash2 size={14} /></button>
                        </div>
                      </div>
                      <p className="text-xs text-gray-500 line-clamp-2 mb-3 leading-relaxed">
                        {ex.description || 'No description provided.'}
                      </p>
                      <div className="flex items-center justify-between">
                        <div className="flex gap-0.5">
                          {[...Array(5)].map((_, i) => (
                            <Star 
                              key={i} 
                              size={10} 
                              fill={i < ex.rating ? 'currentColor' : 'none'} 
                              className={i < ex.rating ? 'text-yellow-400' : 'text-gray-200'} 
                            />
                          ))}
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

const ExerciseForm: React.FC<{ 
  initialData?: Exercise, 
  categories: Category[], 
  onSave: (data: Partial<Exercise>) => void,
  onCancel: () => void
}> = ({ initialData, categories, onSave, onCancel }) => {
