          placeholder="e.g. Chin Tuck"
        />
      </div>
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1">Category</label>
          <select 
            value={formData.category} 
            onChange={e => setFormData({ ...formData, category: e.target.value })}
            className="w-full px-4 py-3 border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500 appearance-none bg-white"
          >
            {categories.map(c => <option key={c.name} value={c.name}>{c.name}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1">Rating</label>
          <div className="flex items-center h-full pt-1">
            {[1,2,3,4,5].map(r => (
              <button 
                key={r} 
                onClick={() => setFormData({ ...formData, rating: r })}
                className={`p-1 ${r <= (formData.rating || 0) ? 'text-yellow-400' : 'text-gray-200'}`}
              >
                <Star size={20} fill={r <= (formData.rating || 0) ? 'currentColor' : 'none'} />
              </button>
            ))}
          </div>
        </div>
      </div>
      <div>
        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1">Description</label>
        <textarea 
          value={formData.description} 
          onChange={e => setFormData({ ...formData, description: e.target.value })}
          className="w-full px-4 py-3 border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
          rows={3}
          placeholder="Step by step instructions..."
        />
      </div>
      <div>
        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1">Video Link (YouTube)</label>
        <input 
          type="text" 
          value={formData.videoUrl} 
          onChange={e => setFormData({ ...formData, videoUrl: e.target.value })}
          className="w-full px-4 py-3 border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
          placeholder="YouTube URL..."
        />
      </div>
      <div className="flex gap-2 pt-4">
        <button 
          onClick={() => onSave(formData)}
          className="flex-1 py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-md"
        >
          {initialData ? 'Update Exercise' : 'Save Exercise'}
        </button>
        <button 
          onClick={onCancel}
          className="px-6 py-3 bg-gray-100 text-gray-600 rounded-xl font-bold hover:bg-gray-200"
        >
          Cancel
        </button>
      </div>
    </div>
  );
};

export default ExerciseLibrary;

import React, { useState, useEffect } from 'react';
import { 
  Tag, 
  LayoutDashboard,
  BookOpen,
  ChevronLeft,
  Library,
  X
} from 'lucide-react';
import { Exercise, Routine, Category, ViewType } from './types';
import { DEFAULT_CATEGORIES } from './constants';
import Sidebar from './components/Sidebar';
import RoutineBuilder from './components/RoutineBuilder';
import CategoryManager from './components/CategoryManager';
import ExerciseLibrary from './components/ExerciseLibrary';

export default function App() {
  const [view, setView] = useState<ViewType>('main');
  const [exercises, setExercises] = useState<Exercise[]>([]);
  const [routines, setRoutines] = useState<Routine[]>([]);
  const [categories, setCategories] = useState<Category[]>(DEFAULT_CATEGORIES);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [activeVideoUrl, setActiveVideoUrl] = useState<string | null>(null);

  // Persistence
  useEffect(() => {
    try {
      const savedExercises = localStorage.getItem('exercises_v4');
      const savedRoutines = localStorage.getItem('routines_v4');
      const savedCategories = localStorage.getItem('categories_v4');

      if (savedExercises) setExercises(JSON.parse(savedExercises));
      if (savedRoutines) setRoutines(JSON.parse(savedRoutines));
      if (savedCategories) setCategories(JSON.parse(savedCategories));
    } catch (e) {
      console.error("Failed to load data", e);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('exercises_v4', JSON.stringify(exercises));
    localStorage.setItem('routines_v4', JSON.stringify(routines));
    localStorage.setItem('categories_v4', JSON.stringify(categories));
  }, [exercises, routines, categories]);

  const handleToggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  const getYoutubeEmbedUrl = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    const id = (match && match[2].length === 11) ? match[2] : null;
    if (!id) return null;
    const origin = window.location.origin;
    return `https://www.youtube.com/embed/${id}?rel=0&modestbranding=1&origin=${encodeURIComponent(origin)}&enablejsapi=1`;
  };

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-50 text-gray-900 font-sans">
      {/* Header */}
      <header className="bg-white border-b px-6 py-3 flex items-center justify-between flex-shrink-0 z-30 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white shadow-sm">
              <LayoutDashboard size={18} />
            </div>
            <h1 className="text-xl font-bold text-gray-800 tracking-tight hidden sm:block">Routine Builder</h1>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => setView('main')}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
              view === 'main' 
                ? 'bg-blue-600 text-white shadow-md' 
                : 'bg-white text-gray-600 hover:bg-gray-100 border border-gray-200'
            }`}
          >
            <LayoutDashboard size={16} /> <span className="hidden md:inline">Builder</span>
          </button>
          <button
            onClick={() => setView('exercises')}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
              view === 'exercises' 
                ? 'bg-blue-600 text-white shadow-md' 
                : 'bg-white text-gray-600 hover:bg-gray-100 border border-gray-200'
            }`}
          >
            <BookOpen size={16} /> <span className="hidden md:inline">Exercise Library</span>
          </button>
          <button
            onClick={() => setView('categories')}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
              view === 'categories' 
                ? 'bg-blue-600 text-white shadow-md' 
                : 'bg-white text-gray-600 hover:bg-gray-100 border border-gray-200'
            }`}
          >
            <Tag size={16} /> <span className="hidden md:inline">Categories</span>
          </button>
        </div>
      </header>

      <main className="flex flex-1 overflow-hidden relative">
        {view === 'main' ? (
          <>
            <div 
              className={`flex h-full relative z-20 transition-all duration-300 ease-in-out ${
                isSidebarOpen ? 'w-1/3 min-w-[340px]' : 'w-10 bg-white border-r border-gray-200'
              }`}
            >
              <aside className={`h-full w-full bg-white transition-opacity duration-300 ${isSidebarOpen ? 'opacity-100 border-r border-gray-200' : 'opacity-0 pointer-events-none'}`}>
                <div className="w-full h-full min-w-[340px]">
                  <Sidebar 
                    exercises={exercises} 
                    setExercises={setExercises} 
                    categories={categories}
                  />
                </div>
              </aside>

              <div 
                className={`absolute top-4 z-50 transition-all duration-300 ${
                  isSidebarOpen ? '-right-4' : 'left-1'
                }`}
              >
                <button 
                  onClick={handleToggleSidebar}
                  className="flex items-center justify-center w-8 h-8 rounded-lg border border-gray-200 bg-white shadow-md text-gray-400 hover:text-blue-600 hover:bg-blue-50 transition-all active:scale-95"
                >
                  {isSidebarOpen ? <ChevronLeft size={20} /> : <Library size={18} />}
                </button>
              </div>

              {!isSidebarOpen && (
                <div 
                  onClick={handleToggleSidebar}
                  className="absolute inset-0 flex flex-col items-center pt-16 cursor-pointer hover:bg-blue-50/50 transition-colors"
                >
                  <div className="flex-1 w-[1px] bg-gray-100 mb-6" />
                  <div className="pb-8 opacity-20 select-none">
                    <p className="text-[9px] font-black tracking-[0.3em] text-gray-900 uppercase rotate-90 origin-center whitespace-nowrap">
                      LIBRARY
                    </p>
                  </div>
                </div>
              )}
            </div>

            <div className="flex-1 overflow-y-auto p-4 sm:p-6 bg-gray-50">
              <div className="max-w-5xl mx-auto">
                <RoutineBuilder 
                  routines={routines} 
                  setRoutines={setRoutines} 
                  exercises={exercises}
                  categories={categories}
                />
              </div>
            </div>
          </>
        ) : view === 'exercises' ? (
          <div className="flex-1 overflow-y-auto p-4 sm:p-6 bg-gray-50">
            <div className="max-w-7xl mx-auto">
              <ExerciseLibrary 
                exercises={exercises}
                setExercises={setExercises}
                categories={categories}
                onPlayVideo={(url) => setActiveVideoUrl(url)}
              />
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-6">
            <div className="max-w-4xl mx-auto">
              <CategoryManager 
                categories={categories} 
                setCategories={setCategories} 
                exercises={exercises}
              />
            </div>
          </div>
        )}
      </main>

      {activeVideoUrl && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl overflow-hidden relative aspect-video">
             <button 
               onClick={() => setActiveVideoUrl(null)}
               className="absolute top-4 right-4 z-20 p-2 bg-black/50 hover:bg-black/80 text-white rounded-full transition-colors shadow-lg"
             >
               <X size={20} />
             </button>
             <iframe
               src={getYoutubeEmbedUrl(activeVideoUrl) || ''}
               className="w-full h-full"
               frameBorder="0"
               allowFullScreen
             />
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { 
  Plus, 
  Edit2, 
  Trash2, 
  Search,
  X,
  Star,
  GripVertical,
  PlayCircle
} from 'lucide-react';
import { Exercise, Category } from '../types';

interface SidebarProps {
  exercises: Exercise[];
  setExercises: React.Dispatch<React.SetStateAction<Exercise[]>>;
  categories: Category[];
}

const getYoutubeEmbedUrl = (url: string) => {
  const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
  const match = url.match(regExp);
  const id = (match && match[2].length === 11) ? match[2] : null;
  if (!id) return null;
  const origin = window.location.origin;
  return `https://www.youtube.com/embed/${id}?rel=0&modestbranding=1&origin=${encodeURIComponent(origin)}&enablejsapi=1`;
};

const Sidebar: React.FC<SidebarProps> = ({ exercises, setExercises, categories }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [expandedVideoId, setExpandedVideoId] = useState<number | null>(null);

  const [formData, setFormData] = useState<Partial<Exercise>>({
    title: '',
    description: '',
    category: categories[0]?.name || 'Mobility',
    videoUrl: '',
    rating: 0
  });

  const resetForm = () => {
    setFormData({
      title: '',
      description: '',
      category: categories[0]?.name || 'Mobility',
      videoUrl: '',
      rating: 0
    });
    setEditingId(null);
    setShowAddForm(false);
  };

  const handleSave = () => {
    if (!formData.title?.trim()) return;

    if (editingId) {
      setExercises(prev => prev.map(ex => ex.id === editingId ? { ...ex, ...formData } as Exercise : ex));
    } else {
      const newEx: Exercise = {
        id: Date.now(),
        title: formData.title || '',
        description: formData.description || '',
        category: formData.category || categories[0]?.name || 'Mobility',
        videoUrl: formData.videoUrl || '',
        rating: formData.rating || 0,
      };
      setExercises(prev => [...prev, newEx]);
    }
    resetForm();
  };

  const handleEdit = (ex: Exercise) => {
    setEditingId(ex.id);
    setFormData({ ...ex });
    setShowAddForm(true);
  };

  const handleDelete = (id: number) => {
    if (confirm("Delete this exercise from library?")) {
      setExercises(prev => prev.filter(e => e.id !== id));
    }
  };

  const filteredExercises = exercises.filter(ex => 
    ex.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    ex.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const grouped = categories.map(cat => ({
    category: cat,
    items: filteredExercises.filter(ex => ex.category === cat.name)
  })).filter(g => g.items.length > 0);

  const StarRating = ({ rating, onRate }: { rating: number; onRate: (r: number) => void }) => (
    <div className="flex gap-1">
      {[1, 2, 3, 4, 5].map(star => (
        <button
          key={star}
          onClick={() => onRate(star)}
          className={`transition-colors ${rating >= star ? 'text-yellow-400' : 'text-gray-300'}`}
        >
          <Star size={16} fill={rating >= star ? 'currentColor' : 'none'} />
        </button>
      ))}
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-white border-r border-gray-100">
      <div className="p-5 border-b border-gray-50 bg-gray-50/30">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-lg font-bold text-gray-800">Exercise Library</h2>
          <button 
            onClick={() => setShowAddForm(true)}
            className="flex items-center gap-1 px-3 py-1.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-all shadow-sm text-sm"
          >
            <Plus size={16} /> <span>New</span>
          </button>
        </div>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
          <input 
            type="text" 
            placeholder="Filter library..." 
            className="w-full pl-10 pr-4 py-2 bg-white border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 shadow-sm"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        {showAddForm && (
          <div className="p-4 bg-gray-50 rounded-xl border border-gray-200 shadow-sm space-y-4 relative animate-in fade-in slide-in-from-top-2 duration-200">
            <button onClick={resetForm} className="absolute top-2 right-2 text-gray-400 hover:text-gray-600">
              <X size={16} />
            </button>
            <h3 className="font-bold text-gray-800 text-sm">{editingId ? 'Update Exercise' : 'Create Exercise'}</h3>

            <div className="space-y-3">
              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Title</label>
                <input 
                  type="text" 
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500"
                  value={formData.title}
                  onChange={e => setFormData({...formData, title: e.target.value})}
                  placeholder="e.g. Chin Tuck Hold"
                />
              </div>

              <div className="flex gap-3">
                <div className="flex-1">
                  <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Category</label>
                  <select 
                    className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500"
                    value={formData.category}
                    onChange={e => setFormData({...formData, category: e.target.value})}
                  >
                    {categories.map(c => <option key={c.name} value={c.name}>{c.name}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Rating</label>
                  <StarRating rating={formData.rating || 0} onRate={r => setFormData({...formData, rating: r})} />
                </div>
              </div>

              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Description</label>
                <textarea 
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500"
                  rows={2}
                  value={formData.description}
                  onChange={e => setFormData({...formData, description: e.target.value})}
                  placeholder="Instructions for the exercise..."
                />
              </div>

              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Video Link (YouTube)</label>
                <input 
                  type="text" 
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500"
                  value={formData.videoUrl}
                  onChange={e => setFormData({...formData, videoUrl: e.target.value})}
                  placeholder="Paste URL to enable in-app player"
                />
              </div>
            </div>

            <div className="flex gap-2 pt-2">
              <button 
                onClick={handleSave}
                className="flex-1 py-2 bg-blue-600 text-white rounded-lg text-sm font-semibold hover:bg-blue-700 shadow-sm"
              >
                {editingId ? 'Save Changes' : 'Add to Library'}
              </button>
            </div>
          </div>
        )}

        {grouped.length === 0 ? (
          <div className="text-center py-10">
            <p className="text-gray-400 text-sm">No exercises found.</p>
          </div>
        ) : (
          grouped.map(({ category, items }) => (
            <div key={category.name} className="space-y-2">
              <div className="flex items-center gap-2 px-1">
                <div className={`w-2 h-2 rounded-full ${category.color}`} />
                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest">{category.name}</h4>
              </div>
              <div className="space-y-1.5">
                {items.map(ex => {
                  const embedUrl = ex.videoUrl ? getYoutubeEmbedUrl(ex.videoUrl) : null;
                  const isExpanded = expandedVideoId === ex.id;

                  return (
                    <div 
                      key={ex.id}
                      draggable
                      onDragStart={(e) => {
                        e.dataTransfer.setData('exerciseId', ex.id.toString());
                      }}
                      className="group flex flex-col bg-white border border-gray-100 rounded-xl hover:border-blue-200 hover:shadow-md transition-all"
                    >
                      <div className="flex items-center gap-2 p-3">
                        <GripVertical size={16} className="text-gray-300 group-hover:text-blue-400 transition-colors cursor-grab active:cursor-grabbing" />
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-1.5">
                            <p className="text-sm font-semibold text-gray-700 truncate">{ex.title}</p>
                            {embedUrl && (
                              <button 
                                onClick={() => setExpandedVideoId(isExpanded ? null : ex.id)}
                                className={`transition-colors ${isExpanded ? 'text-blue-700' : 'text-blue-500 hover:text-blue-700'}`}
                              >
                                <PlayCircle size={14} />
                              </button>
                            )}
                          </div>
                          {ex.rating > 0 && (
                            <div className="flex items-center gap-0.5 mt-0.5">
                              {[...Array(ex.rating)].map((_, i) => (
                                <div key={i} className="w-1.5 h-1.5 rounded-full bg-yellow-400" />
                              ))}
                            </div>
                          )}
                        </div>
                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => handleEdit(ex)}
                            className="p-1.5 hover:bg-gray-100 rounded-lg text-gray-400 hover:text-blue-500"
                          >
                            <Edit2 size={14} />
                          </button>
                          <button 
                            onClick={() => handleDelete(ex.id)}
                            className="p-1.5 hover:bg-red-50 rounded-lg text-gray-400 hover:text-red-500"
                          >
                            <Trash2 size={14} />
                          </button>
                        </div>
                      </div>

                      {isExpanded && embedUrl && (
                        <div className="px-3 pb-3 pt-0 animate-in slide-in-from-top-2 duration-200">
                          <div className="relative aspect-video w-full rounded-lg overflow-hidden bg-black border border-gray-200">
                            <iframe
                              src={embedUrl}
                              className="w-full h-full"
                              frameBorder="0"
                              allowFullScreen
                              referrerPolicy="strict-origin-when-cross-origin"
                            />
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default Sidebar;

export interface User {
  id: string;
  email: string;
  name: string;
  avatar?: string;
}

export interface Exercise {
  id: number;
  title: string;
  description: string;
  category: string;
  videoUrl: string;
  rating: number;
}

