import React, { useState, useEffect } from 'react';
import { 
  Tag, 
  LayoutDashboard,
  BookOpen,
  ChevronLeft,
  Library,
  X,
  LogOut,
  User as UserIcon,
  Calendar
} from 'lucide-react';
import { Exercise, Routine, Category, ViewType, User, ScheduledRoutine } from './types';
import { DEFAULT_CATEGORIES } from './constants';
