      setIsLoading(false);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        setUser({
          id: session.user.id,
          email: session.user.email!,
          name: session.user.user_metadata.full_name || session.user.email!,
        });
      } else {
        setUser(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (!user) return;

    const fetchData = async () => {
      const [exRes, rtRes, catRes, schRes] = await Promise.all([
        supabase.from('exercises').select('*').eq('user_id', user.id),
        supabase.from('routines').select('*').eq('user_id', user.id).order('id', { ascending: false }),
        supabase.from('categories').select('*').eq('user_id', user.id),
        supabase.from('scheduled_routines').select('*').eq('user_id', user.id)
      ]);

      if (exRes.data) setExercises(exRes.data);
      if (rtRes.data) setRoutines(rtRes.data);
      if (catRes.data && catRes.data.length > 0) setCategories(catRes.data);
      if (schRes.data) setScheduledRoutines(schRes.data);
    };

    fetchData();
  }, [user]);

  const handleToggleSidebar = () => {
    setIsSidebarOpen(prev => !prev);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setUser(null);
    setShowProfileMenu(false);
  };

  const getYoutubeEmbedUrl = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    const id = (match && match[2].length === 11) ? match[2] : null;
    if (!id) return null;
    return `https://www.youtube.com/embed/${id}?rel=0&modestbranding=1`;
  };

  if (isLoading) {
    return (
      <div className="h-screen flex items-center justify-center bg-gray-50">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
      </div>
    );
  }

  if (!user) {
    return <Auth onLogin={() => {}} />;
  }

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-white text-gray-900 font-sans">
      <header className="bg-white border-b px-4 py-2 flex items-center justify-between flex-shrink-0 z-30 shadow-sm">
        <div className="flex items-center gap-3">
          <button 
            onClick={handleToggleSidebar}
            className="p-2 hover:bg-gray-100 rounded-lg text-gray-500 transition-colors"
          >
            {isSidebarOpen ? <PanelLeftClose size={20} /> : <PanelLeftOpen size={20} />}
          </button>
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-sm">
              <LayoutDashboard size={18} />
            </div>
            <h1 className="text-lg font-bold text-gray-800 tracking-tight hidden sm:block">FlowState</h1>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <div className="flex items-center bg-gray-100 p-1 rounded-xl mr-2">
            <button
              onClick={() => setView('main')}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${
                view === 'main' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:bg-gray-200'
              }`}
            >
              <LayoutDashboard size={14} /> <span className="hidden lg:inline uppercase tracking-widest">Builder</span>
            </button>
            <button
              onClick={() => setView('exercises')}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${
                view === 'exercises' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:bg-gray-200'
              }`}
            >
              <BookOpen size={14} /> <span className="hidden lg:inline uppercase tracking-widest">Library</span>
            </button>
            <button
              onClick={() => setView('calendar')}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${
                view === 'calendar' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:bg-gray-200'
              }`}
            >
              <Calendar size={14} /> <span className="hidden lg:inline uppercase tracking-widest">Schedule</span>
            </button>
            <button
              onClick={() => setView('categories')}
              className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${
                view === 'categories' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500 hover:bg-gray-200'
              }`}
            >
              <Tag size={14} /> <span className="hidden lg:inline uppercase tracking-widest">Labels</span>
            </button>
          </div>

          <div className="relative">
            <button 
              onClick={() => setShowProfileMenu(!showProfileMenu)}
              className="w-8 h-8 bg-indigo-50 border border-indigo-100 rounded-full flex items-center justify-center text-indigo-600 font-bold hover:bg-indigo-100 transition-colors uppercase text-xs"
            >
              {user.name.split(' ').map(n => n[0]).join('')}
            </button>

            {showProfileMenu && (
              <div className="absolute right-0 mt-2 w-48 bg-white rounded-xl shadow-xl border border-gray-100 p-1 animate-in slide-in-from-top-2 duration-200 z-50">
                <div className="px-4 py-2 border-b border-gray-50 mb-1">
                  <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Account</p>
                  <p className="text-xs font-bold text-gray-800 truncate">{user.name}</p>
                </div>
                <button 
                  onClick={handleLogout}
                  className="w-full flex items-center gap-3 px-4 py-2 text-xs text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                >
                  <LogOut size={14} /> Sign Out
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <main className="flex flex-1 overflow-hidden">
        {view === 'main' ? (
          <div className="flex flex-1 w-full">
            <aside 
              className={`h-full bg-white transition-all duration-300 ease-in-out border-r border-gray-100 overflow-hidden ${
                isSidebarOpen ? 'w-1/3 min-w-[320px]' : 'w-0'
              }`}
            >
              <div className="w-full h-full min-w-[320px]">
                <Sidebar 
                  exercises={exercises} 
                  setExercises={setExercises} 
                  categories={categories}
                />
