            </aside>
            <section className="flex-1 overflow-y-auto bg-gray-50/50">
              <div className="p-6 max-w-5xl mx-auto">
                <RoutineBuilder 
                  routines={routines} 
                  setRoutines={setRoutines} 
                  exercises={exercises}
                  categories={categories}
