import React, { useState } from 'react';
import { 
  Plus, 
  Edit2, 
  Trash2, 
  Search,
  X,
  Star,
  GripVertical,
  PlayCircle
} from 'lucide-react';
import { Exercise, Category } from '../types.ts';

interface SidebarProps {
  exercises: Exercise[];
  setExercises: React.Dispatch<React.SetStateAction<Exercise[]>>;
  categories: Category[];
}

const Sidebar: React.FC<SidebarProps> = ({ exercises, setExercises, categories }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);

  const [formData, setFormData] = useState<Partial<Exercise>>({
    title: '',
    description: '',
    category: categories[0]?.name || 'Mobility',
    videoUrl: '',
    rating: 0
  });

  const resetForm = () => {
    setFormData({
      title: '',
      description: '',
      category: categories[0]?.name || 'Mobility',
      videoUrl: '',
      rating: 0
    });
    setEditingId(null);
    setShowAddForm(false);
  };

  const handleSave = () => {
    if (!formData.title?.trim()) return;

    if (editingId) {
      setExercises(prev => prev.map(ex => ex.id === editingId ? { ...ex, ...formData } as Exercise : ex));
    } else {
      const newEx: Exercise = {
        id: Date.now(),
        title: formData.title || '',
        description: formData.description || '',
        category: formData.category || categories[0]?.name || 'Mobility',
        videoUrl: formData.videoUrl || '',
        rating: formData.rating || 0,
      };
      setExercises(prev => [...prev, newEx]);
    }
    resetForm();
  };

  const filteredExercises = exercises.filter(ex => 
    ex.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    ex.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const grouped = categories.map(cat => ({
    category: cat,
    items: filteredExercises.filter(ex => ex.category === cat.name)
  })).filter(g => g.items.length > 0);

  return (
    <div className="flex flex-col h-full bg-white border-r border-gray-100">
      <div className="p-4 border-b border-gray-50">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-sm font-black uppercase tracking-widest text-gray-400">Exercise Library</h2>
          <button 
            onClick={() => setShowAddForm(true)}
            className="p-1.5 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-all shadow-sm"
          >
            <Plus size={16} />
          </button>
        </div>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-300" size={14} />
          <input 
            type="text" 
            placeholder="Search..." 
            className="w-full pl-9 pr-4 py-2 bg-gray-50 border border-gray-100 rounded-lg text-xs focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-3 space-y-6">
        {showAddForm && (
          <div className="p-4 bg-gray-50 rounded-xl border border-gray-200 space-y-3 relative animate-in fade-in slide-in-from-top-2">
            <button onClick={resetForm} className="absolute top-2 right-2 text-gray-400">
              <X size={14} />
            </button>
            <h3 className="font-bold text-gray-800 text-xs">{editingId ? 'Edit' : 'New'} Exercise</h3>
            <input 
              type="text" 
              placeholder="Exercise Title"
              className="w-full px-3 py-2 text-xs border border-gray-200 rounded-lg"
              value={formData.title}
              onChange={e => setFormData({...formData, title: e.target.value})}
            />
            <select 
              className="w-full px-3 py-2 text-xs border border-gray-200 rounded-lg bg-white"
              value={formData.category}
              onChange={e => setFormData({...formData, category: e.target.value})}
            >
              {categories.map(c => <option key={c.name} value={c.name}>{c.name}</option>)}
            </select>
            <textarea 
              placeholder="Description"
              className="w-full px-3 py-2 text-xs border border-gray-200 rounded-lg"
              rows={2}
              value={formData.description}
              onChange={e => setFormData({...formData, description: e.target.value})}
            />
            <input 
              type="text" 
              placeholder="Video URL"
              className="w-full px-3 py-2 text-xs border border-gray-200 rounded-lg"
              value={formData.videoUrl}
              onChange={e => setFormData({...formData, videoUrl: e.target.value})}
            />
            <button 
              onClick={handleSave}
              className="w-full py-2 bg-indigo-600 text-white rounded-lg text-xs font-bold hover:bg-indigo-700 shadow-sm"
            >
              Save Exercise
            </button>
          </div>
        )}

        {grouped.map(({ category, items }) => (
          <div key={category.name} className="space-y-1.5">
            <div className="flex items-center gap-2 px-1">
              <div className={`w-2 h-2 rounded-full ${category.color}`} />
              <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{category.name}</h4>
            </div>
            {items.map(ex => (
              <div 
                key={ex.id}
                draggable
                onDragStart={(e) => {
                  e.dataTransfer.setData('exerciseId', ex.id.toString());
                }}
                className="group flex items-center gap-2 p-2 bg-white border border-gray-100 rounded-lg hover:border-indigo-200 hover:shadow-sm transition-all cursor-grab active:cursor-grabbing"
              >
                <GripVertical size={14} className="text-gray-200 group-hover:text-indigo-300" />
                <div className="flex-1 min-w-0">
                  <p className="text-xs font-bold text-gray-700 truncate">{ex.title}</p>
                  <p className="text-[10px] text-gray-400 truncate italic">{ex.description}</p>
                </div>
                <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button 
                    onClick={() => { setEditingId(ex.id); setFormData(ex); setShowAddForm(true); }}
                    className="p-1 hover:bg-indigo-50 rounded text-indigo-400"
                  >
                    <Edit2 size={12} />
                  </button>
                  <button 
                    onClick={() => setExercises(prev => prev.filter(e => e.id !== ex.id))}
                    className="p-1 hover:bg-red-50 rounded text-red-400"
                  >
                    <Trash2 size={12} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        ))}
      </div>
    </div>
  );
};

