          </div>
        </div>

        <div className="flex items-center gap-2">
          <nav className="flex items-center bg-gray-100 p-1 rounded-xl mr-2">
            {[
              { id: 'main', icon: LayoutDashboard, label: 'Builder' },
              { id: 'exercises', icon: BookOpen, label: 'Library' },
              { id: 'calendar', icon: CalendarIcon, label: 'Schedule' },
              { id: 'categories', icon: Tag, label: 'Labels' }
            ].map((nav) => (
              <button
