              className="w-8 h-8 bg-indigo-50 border border-indigo-100 rounded-full flex items-center justify-center text-indigo-600 font-bold uppercase text-xs hover:bg-indigo-100"
            >
              {user.name[0]}
            </button>
            {showProfileMenu && (
              <div className="absolute right-0 mt-2 w-48 bg-white rounded-xl shadow-xl border border-gray-100 p-1 z-50">
                <div className="px-4 py-2 border-b border-gray-50 mb-1">
                  <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Account</p>
                  <p className="text-xs font-bold text-gray-800 truncate">{user.name}</p>
                </div>
                <button 
                  onClick={() => setUser(null)}
                  className="w-full flex items-center gap-3 px-4 py-2 text-xs text-red-500 hover:bg-red-50 rounded-lg transition-colors"
