import React, { useState } from 'react';
import { 
  Plus, 
  Trash2, 
  ChevronDown, 
  ChevronRight, 
  GripVertical,
  Layers,
  Clock,
  Maximize2,
  Minimize2
} from 'lucide-react';
import { Routine, Exercise, Category, ExerciseItem } from '../types.ts';

interface RoutineBuilderProps {
  routines: Routine[];
  setRoutines: React.Dispatch<React.SetStateAction<Routine[]>>;
  exercises: Exercise[];
  categories: Category[];
}

const CompactExerciseRow: React.FC<{ 
  exerciseId: number; 
  onRemove: () => void; 
  exercises: Exercise[]; 
  categories: Category[];
  onDragStart: (e: React.DragEvent) => void;
  onDrop: (e: React.DragEvent) => void;
}> = ({ exerciseId, onRemove, exercises, categories, onDragStart, onDrop }) => {
  const ex = exercises.find(e => e.id === exerciseId);
  if (!ex) return null;

  const catColor = categories.find(c => c.name === ex.category)?.color || 'bg-gray-400';

  return (
    <div 
      draggable
      onDragStart={onDragStart}
      onDragOver={e => e.preventDefault()}
      onDrop={onDrop}
      className="group flex items-center gap-3 px-3 py-1.5 bg-white border-b border-gray-50 last:border-0 hover:bg-indigo-50/30 transition-colors"
    >
      <div className="flex-shrink-0 cursor-grab active:cursor-grabbing">
        <GripVertical size={14} className="text-gray-300 group-hover:text-indigo-400" />
      </div>

      <div className="flex-1 min-w-0 flex items-center gap-2 overflow-hidden text-xs">
        <span className="font-bold text-gray-800 whitespace-nowrap">{ex.title}</span>
        <span className="text-gray-300">|</span>
        <span className={`px-1.5 py-0.5 rounded text-[9px] font-black uppercase tracking-wider text-white whitespace-nowrap ${catColor}`}>
          {ex.category}
        </span>
        <span className="text-gray-300">|</span>
        <span className="text-gray-500 truncate flex-1 italic">
          {ex.description || 'No description'}
        </span>
      </div>

      <button 
        onClick={onRemove}
        className="p-1 opacity-0 group-hover:opacity-100 hover:bg-red-50 rounded text-red-400 hover:text-red-600 transition-all"
      >
        <Trash2 size={12} />
      </button>
    </div>
  );
};

const RoutineBuilder: React.FC<RoutineBuilderProps> = ({ routines, setRoutines, exercises, categories }) => {
  const createRoutine = () => {
    const newRoutine: Routine = {
      id: Date.now(),
      name: 'New Routine',
      exerciseItems: [],
      subRoutines: [],
      isExpanded: true
    };
    setRoutines([newRoutine, ...routines]);
  };

  const updateRoutine = (id: number, updates: Partial<Routine>) => {
    setRoutines(prev => prev.map(r => r.id === id ? { ...r, ...updates } : r));
  };

  const addSection = (routineId: number) => {
    setRoutines(prev => prev.map(r => {
      if (r.id === routineId) {
        return {
          ...r,
          subRoutines: [...r.subRoutines, { id: Date.now(), name: 'New Section', exerciseItems: [], isExpanded: true }]
        };
      }
      return r;
    }));
  };

  const toggleExerciseInRoutine = (routineId: number, exerciseId: number, subRoutineId?: number) => {
    setRoutines(prev => prev.map(r => {
      if (r.id !== routineId) return r;
      if (subRoutineId) {
        const sr = r.subRoutines.find(s => s.id === subRoutineId);
        const isAdded = sr?.exerciseItems.some(i => i.exerciseId === exerciseId);
        return {
          ...r,
          subRoutines: r.subRoutines.map(s => {
            if (s.id !== subRoutineId) return s;
            if (isAdded) return { ...s, exerciseItems: s.exerciseItems.filter(i => i.exerciseId !== exerciseId) };
            return { ...s, exerciseItems: [...s.exerciseItems, { exerciseId }] };
          })
        };
      } else {
        const isAdded = r.exerciseItems.some(i => i.exerciseId === exerciseId);
        if (isAdded) return { ...r, exerciseItems: r.exerciseItems.filter(i => i.exerciseId !== exerciseId) };
        return { ...r, exerciseItems: [...r.exerciseItems, { exerciseId }] };
      }
    }));
  };

  const handleExerciseDragStart = (e: React.DragEvent, routineId: number, idx: number, subRoutineId?: number) => {
    e.dataTransfer.setData('sourceRoutineId', routineId.toString());
    e.dataTransfer.setData('sourceIdx', idx.toString());
    if (subRoutineId) e.dataTransfer.setData('sourceSubRoutineId', subRoutineId.toString());
  };

  const handleExerciseDropInternal = (e: React.DragEvent, routineId: number, targetIdx: number, targetSubRoutineId?: number) => {
    e.preventDefault();
    const sourceRoutineIdStr = e.dataTransfer.getData('sourceRoutineId');
    if (!sourceRoutineIdStr) {
      const eid = e.dataTransfer.getData('exerciseId');
      if (eid) toggleExerciseInRoutine(routineId, parseInt(eid), targetSubRoutineId);
      return;
    };
    const sourceRoutineId = parseInt(sourceRoutineIdStr);
    const sourceIdx = parseInt(e.dataTransfer.getData('sourceIdx'));
    const sourceSubRoutineIdStr = e.dataTransfer.getData('sourceSubRoutineId');
    const sourceSubRoutineId = sourceSubRoutineIdStr ? parseInt(sourceSubRoutineIdStr) : undefined;
    if (sourceRoutineId !== routineId) return;

    setRoutines(prev => prev.map(r => {
      if (r.id !== routineId) return r;
      const newR = JSON.parse(JSON.stringify(r)) as Routine;
      let itemToMove: ExerciseItem | undefined;
      if (sourceSubRoutineId) {
        const sr = newR.subRoutines.find(s => s.id === sourceSubRoutineId);
        if (sr) itemToMove = sr.exerciseItems.splice(sourceIdx, 1)[0];
      } else {
        itemToMove = newR.exerciseItems.splice(sourceIdx, 1)[0];
      }
      if (!itemToMove) return r;
      if (targetSubRoutineId) {
        const sr = newR.subRoutines.find(s => s.id === targetSubRoutineId);
        if (sr) sr.exerciseItems.splice(targetIdx, 0, itemToMove);
      } else {
        newR.exerciseItems.splice(targetIdx, 0, itemToMove);
      }
      return newR;
    }));
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center bg-white p-4 rounded-xl shadow-sm border border-gray-100">
        <div>
          <h2 className="text-lg font-bold text-gray-800">Routine Builder</h2>
          <p className="text-xs text-gray-500">Drag exercises into your routines below</p>
        </div>
        <div className="flex gap-2">
           <button 
            onClick={() => routines.forEach(r => updateRoutine(r.id, { isExpanded: false }))}
            className="p-2 bg-gray-100 text-gray-500 rounded-lg hover:bg-gray-200"
            title="Collapse All"
          >
            <Minimize2 size={18} />
          </button>
          <button 
            onClick={createRoutine}
            className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg font-bold hover:bg-indigo-700 shadow-md transition-all active:scale-95 text-sm"
          >
            <Plus size={18} /> New Routine
          </button>
        </div>
      </div>

      <div className="space-y-3">
        {routines.map((routine) => (
          <div key={routine.id} className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden">
            <div className="flex items-center gap-2 p-2 px-3 bg-gray-50/50 border-b border-gray-50">
              <button 
                onClick={() => updateRoutine(routine.id, { isExpanded: !routine.isExpanded })}
                className="p-1 hover:bg-gray-200 rounded text-gray-400"
              >
                {routine.isExpanded ? <ChevronDown size={18} /> : <ChevronRight size={18} />}
              </button>
              <input 
                type="text" 
                value={routine.name} 
                onChange={(e) => updateRoutine(routine.id, { name: e.target.value })}
                className="bg-transparent font-bold text-gray-700 focus:outline-none flex-1 truncate text-sm"
              />
              <div className="flex items-center gap-1">
                <button 
                  onClick={() => addSection(routine.id)}
                  className="p-1.5 hover:bg-indigo-50 text-indigo-600 rounded-lg"
                  title="Add Section"
                >
                  <Layers size={16} />
                </button>
                <button 
                  onClick={() => setRoutines(routines.filter(r => r.id !== routine.id))}
                  className="p-1.5 hover:bg-red-50 text-red-500 rounded-lg"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </div>

            {routine.isExpanded && (
              <div className="p-1 space-y-2">
                <div 
                  onDragOver={e => e.preventDefault()}
                  onDrop={e => handleExerciseDropInternal(e, routine.id, routine.exerciseItems.length)}
                  className="border border-gray-50 rounded-lg overflow-hidden min-h-[40px]"
                >
                  {routine.exerciseItems.map((item, idx) => (
                    <CompactExerciseRow 
                      key={`${item.exerciseId}-${idx}`}
                      exerciseId={item.exerciseId}
                      exercises={exercises}
                      categories={categories}
                      onRemove={() => {
                        const newItems = [...routine.exerciseItems];
                        newItems.splice(idx, 1);
                        updateRoutine(routine.id, { exerciseItems: newItems });
                      }}
                      onDragStart={(e) => handleExerciseDragStart(e, routine.id, idx)}
                      onDrop={(e) => { e.stopPropagation(); handleExerciseDropInternal(e, routine.id, idx); }}
                    />
                  ))}
                  {routine.exerciseItems.length === 0 && (
                    <div className="p-4 text-center text-[10px] text-gray-300 uppercase tracking-widest italic">
                      Drop exercises here
                    </div>
                  )}
                </div>

                {routine.subRoutines.map((sr) => (
                  <div key={sr.id} className="bg-gray-50/20 border border-gray-50 rounded-lg overflow-hidden ml-2">
                    <div className="flex items-center gap-2 p-1.5 px-3 bg-white border-b border-gray-50">
                      <button 
                        onClick={() => {
                          const newSubRoutines = routine.subRoutines.map(s => s.id === sr.id ? {...s, isExpanded: !s.isExpanded} : s);
                          updateRoutine(routine.id, { subRoutines: newSubRoutines });
                        }}
                        className="text-gray-400"
                      >
                        {sr.isExpanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                      </button>
                      <input 
                        type="text" 
                        value={sr.name} 
                        onChange={(e) => {
                          const newSubRoutines = routine.subRoutines.map(s => s.id === sr.id ? {...s, name: e.target.value} : s);
                          updateRoutine(routine.id, { subRoutines: newSubRoutines });
                        }}
                        className="bg-transparent text-xs font-bold text-gray-500 focus:outline-none flex-1"
                      />
                      <button 
                        onClick={() => {
                          const newSubRoutines = routine.subRoutines.filter(s => s.id !== sr.id);
                          updateRoutine(routine.id, { subRoutines: newSubRoutines });
                        }}
                        className="p-1 hover:bg-red-50 rounded text-red-400"
                      >
                        <Trash2 size={12} />
                      </button>
                    </div>
                    {sr.isExpanded && (
                      <div 
                        onDragOver={e => e.preventDefault()}
                        onDrop={e => { e.stopPropagation(); handleExerciseDropInternal(e, routine.id, sr.exerciseItems.length, sr.id); }}
                        className="min-h-[30px]"
                      >
                        {sr.exerciseItems.map((item, idx) => (
                          <CompactExerciseRow 
                            key={`${item.exerciseId}-${idx}`}
                            exerciseId={item.exerciseId}
                            exercises={exercises}
                            categories={categories}
                            onRemove={() => {
                              const newSRs = routine.subRoutines.map(s => {
                                if (s.id !== sr.id) return s;
                                const newItems = [...s.exerciseItems];
                                newItems.splice(idx, 1);
                                return { ...s, exerciseItems: newItems };
                              });
                              updateRoutine(routine.id, { subRoutines: newSRs });
                            }}
                            onDragStart={(e) => handleExerciseDragStart(e, routine.id, idx, sr.id)}
                            onDrop={(e) => { e.stopPropagation(); handleExerciseDropInternal(e, routine.id, idx, sr.id); }}
                          />
                        ))}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default RoutineBuilder;

import React, { useState } from 'react';
import { 
  Plus, 
  Edit2, 
  Trash2, 
  Search,
  X,
  GripVertical
} from 'lucide-react';
import { Exercise, Category } from '../types.ts';

interface SidebarProps {
  exercises: Exercise[];
  setExercises: React.Dispatch<React.SetStateAction<Exercise[]>>;
  categories: Category[];
}

const Sidebar: React.FC<SidebarProps> = ({ exercises, setExercises, categories }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);

  const [formData, setFormData] = useState<Partial<Exercise>>({
    title: '',
    description: '',
    category: categories[0]?.name || 'Mobility',
    videoUrl: '',
    rating: 0
  });

  const resetForm = () => {
    setFormData({
      title: '',
      description: '',
      category: categories[0]?.name || 'Mobility',
      videoUrl: '',
      rating: 0
    });
    setEditingId(null);
    setShowAddForm(false);
  };

  const handleSave = () => {
    if (!formData.title?.trim()) return;
    if (editingId) {
      setExercises(prev => prev.map(ex => ex.id === editingId ? { ...ex, ...formData } as Exercise : ex));
    } else {
      const newEx: Exercise = {
        id: Date.now(),
        title: formData.title || '',
        description: formData.description || '',
        category: formData.category || categories[0]?.name || 'Mobility',
        videoUrl: formData.videoUrl || '',
        rating: formData.rating || 0,
      };
      setExercises(prev => [...prev, newEx]);
    }
    resetForm();
  };

  const filteredExercises = exercises.filter(ex => 
    ex.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    ex.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const grouped = categories.map(cat => ({
    category: cat,
    items: filteredExercises.filter(ex => ex.category === cat.name)
  })).filter(g => g.items.length > 0);

  return (
    <div className="flex flex-col h-full bg-white border-r border-gray-100">
      <div className="p-4 border-b border-gray-50">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-sm font-black uppercase tracking-widest text-gray-400">Exercise Library</h2>
          <button 
            onClick={() => setShowAddForm(true)}
            className="p-1.5 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-all shadow-sm"
          >
            <Plus size={16} />
          </button>
        </div>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-300" size={14} />
          <input 
            type="text" 
            placeholder="Search..." 
            className="w-full pl-9 pr-4 py-2 bg-gray-50 border border-gray-100 rounded-lg text-xs focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-3 space-y-6">
        {showAddForm && (
          <div className="p-4 bg-gray-50 rounded-xl border border-gray-200 space-y-3 relative animate-in fade-in slide-in-from-top-2">
            <button onClick={resetForm} className="absolute top-2 right-2 text-gray-400">
              <X size={14} />
            </button>
            <h3 className="font-bold text-gray-800 text-xs">{editingId ? 'Edit' : 'New'} Exercise</h3>
            <input 
              type="text" 
              placeholder="Exercise Title"
              className="w-full px-3 py-2 text-xs border border-gray-200 rounded-lg focus:ring-1 focus:ring-indigo-300"
              value={formData.title}
              onChange={e => setFormData({...formData, title: e.target.value})}
            />
            <select 
              className="w-full px-3 py-2 text-xs border border-gray-200 rounded-lg bg-white focus:ring-1 focus:ring-indigo-300"
              value={formData.category}
              onChange={e => setFormData({...formData, category: e.target.value})}
            >
              {categories.map(c => <option key={c.name} value={c.name}>{c.name}</option>)}
            </select>
            <textarea 
              placeholder="Brief Description"
              className="w-full px-3 py-2 text-xs border border-gray-200 rounded-lg focus:ring-1 focus:ring-indigo-300"
              rows={2}
              value={formData.description}
              onChange={e => setFormData({...formData, description: e.target.value})}
            />
            <input 
              type="text" 
              placeholder="YouTube URL (Optional)"
              className="w-full px-3 py-2 text-xs border border-gray-200 rounded-lg focus:ring-1 focus:ring-indigo-300"
              value={formData.videoUrl}
              onChange={e => setFormData({...formData, videoUrl: e.target.value})}
            />
            <button 
              onClick={handleSave}
              className="w-full py-2 bg-indigo-600 text-white rounded-lg text-xs font-bold hover:bg-indigo-700 shadow-sm"
            >
              Save Exercise
            </button>
          </div>
        )}

        {grouped.map(({ category, items }) => (
          <div key={category.name} className="space-y-1.5">
            <div className="flex items-center gap-2 px-1">
              <div className={`w-2 h-2 rounded-full ${category.color}`} />
              <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{category.name}</h4>
            </div>
            {items.map(ex => (
              <div 
                key={ex.id}
                draggable
                onDragStart={(e) => {
                  e.dataTransfer.setData('exerciseId', ex.id.toString());
                }}
                className="group flex items-center gap-2 p-2 bg-white border border-gray-100 rounded-lg hover:border-indigo-200 hover:shadow-sm transition-all cursor-grab active:cursor-grabbing"
              >
                <GripVertical size={14} className="text-gray-200 group-hover:text-indigo-300" />
                <div className="flex-1 min-w-0">
                  <p className="text-xs font-bold text-gray-700 truncate">{ex.title}</p>
                  <p className="text-[10px] text-gray-400 truncate italic">{ex.description || 'No description'}</p>
                </div>
                <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button 
                    onClick={() => { setEditingId(ex.id); setFormData(ex); setShowAddForm(true); }}
                    className="p-1 hover:bg-indigo-50 rounded text-indigo-400"
                  >
                    <Edit2 size={12} />
                  </button>
                  <button 
                    onClick={() => setExercises(prev => prev.filter(e => e.id !== ex.id))}
                    className="p-1 hover:bg-red-50 rounded text-red-400"
                  >
                    <Trash2 size={12} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        ))}
        {exercises.length === 0 && !showAddForm && (
          <div className="text-center py-10">
            <p className="text-[10px] text-gray-300 uppercase font-black">Empty Library</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Sidebar;

export interface User {
  id: string;
  email: string;
  name: string;
  avatar?: string;
}

export interface Exercise {
  id: number;
  title: string;
  description: string;
  categories: string[]; // Changed from category: string
  videoUrl: string;
  rating: number;
}

export interface ExerciseItem {
  exerciseId: number;
}

export interface SubRoutine {
  id: number;
  name: string;
  exerciseItems: ExerciseItem[];
  isExpanded?: boolean;
}

export interface RoutineSchedule {
  duration: number; // minutes
  timeOfDay: string; // HH:mm
  daysOfWeek: string[]; // ['MO', 'TU', etc]
  frequency: 'daily' | 'weekdays' | 'weekly' | 'monthly' | 'custom';
}

export interface Routine {
  id: number;
  name: string;
  exerciseItems: ExerciseItem[];
  subRoutines: SubRoutine[];
  isExpanded?: boolean;
  schedule?: RoutineSchedule;
}

/**
 * ScheduledRoutine represents a specific instance of a routine on the calendar.
 */
export interface ScheduledRoutine {
  id: string;
  routineId: number;
  date: string; // ISO string YYYY-MM-DD
  duration: number;
  recurrence: 'once' | 'daily' | 'weekly' | 'weekdays';
}

export interface Category {
  name: string;
  color: string;
}

export type ViewType = 'main' | 'categories' | 'exercises' | 'calendar';

import React, { useState, useEffect } from 'react';
import { 
  Tag, 
  LayoutDashboard,
  BookOpen,
  ChevronLeft,
  Library,
  X,
  LogOut,
  User as UserIcon,
  Calendar as CalendarIcon
} from 'lucide-react';
import { Exercise, Routine, Category, ViewType, User, ScheduledRoutine } from './types';
import { DEFAULT_CATEGORIES } from './constants';
import Sidebar from './components/Sidebar';
import RoutineBuilder from './components/RoutineBuilder';
import CategoryManager from './components/CategoryManager';
import ExerciseLibrary from './components/ExerciseLibrary';
import Auth from './components/Auth';
import CalendarView from './components/CalendarView';

export default function App() {
  // Default user to bypass login screen as requested
  const [user, setUser] = useState<User | null>({
    id: 'tester_001',
    email: 'tester@example.com',
    name: 'Testing User'
  });

  const [view, setView] = useState<ViewType>('main');
  const [exercises, setExercises] = useState<Exercise[]>([]);
  const [routines, setRoutines] = useState<Routine[]>([]);
  const [scheduledRoutines, setScheduledRoutines] = useState<ScheduledRoutine[]>([]);
  const [categories, setCategories] = useState<Category[]>(DEFAULT_CATEGORIES);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [activeVideoUrl, setActiveVideoUrl] = useState<string | null>(null);
  const [showProfileMenu, setShowProfileMenu] = useState(false);
  const [dataLoaded, setDataLoaded] = useState(false);

  // Load Data
  useEffect(() => {
    if (!user) {
      setDataLoaded(false);
      return;
    }

    try {
      const storageKeySuffix = `_${user.id}`;
      const savedExercises = localStorage.getItem(`exercises${storageKeySuffix}`);
      const savedRoutines = localStorage.getItem(`routines${storageKeySuffix}`);
      const savedCategories = localStorage.getItem(`categories${storageKeySuffix}`);
      const savedScheduled = localStorage.getItem(`scheduledRoutines${storageKeySuffix}`);

      if (savedExercises) {
        const parsed = JSON.parse(savedExercises);
        // Migrating old data if necessary: convert category string to categories array
        const migrated = parsed.map((ex: any) => ({
          ...ex,
          categories: Array.isArray(ex.categories) ? ex.categories : (ex.category ? [ex.category] : [])
        }));
        setExercises(migrated);
      }
      if (savedRoutines) setRoutines(JSON.parse(savedRoutines));
      if (savedCategories) setCategories(JSON.parse(savedCategories));
      if (savedScheduled) setScheduledRoutines(JSON.parse(savedScheduled));

      setDataLoaded(true);
    } catch (e) {
      console.error("Failed to load data", e);
      setDataLoaded(true);
    }
  }, [user]);

  // Save Data
  useEffect(() => {
    if (!user || !dataLoaded) return;

    const storageKeySuffix = `_${user.id}`;
    localStorage.setItem(`exercises${storageKeySuffix}`, JSON.stringify(exercises));
    localStorage.setItem(`routines${storageKeySuffix}`, JSON.stringify(routines));
    localStorage.setItem(`categories${storageKeySuffix}`, JSON.stringify(categories));
    localStorage.setItem(`scheduledRoutines${storageKeySuffix}`, JSON.stringify(scheduledRoutines));
  }, [exercises, routines, categories, scheduledRoutines, user, dataLoaded]);

  const handleToggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  const handleLogout = () => {
    setUser(null);
    setShowProfileMenu(false);
    setDataLoaded(false);
  };

  const getYoutubeEmbedUrl = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    const id = (match && match[2].length === 11) ? match[2] : null;
    if (!id) return null;
    return `https://www.youtube.com/embed/${id}?rel=0&modestbranding=1&enablejsapi=1`;
  };

  if (!user) {
    return <Auth onLogin={setUser} />;
  }

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-50 text-gray-900 font-sans">
      {/* Header */}
      <header className="bg-white border-b px-6 py-3 flex items-center justify-between flex-shrink-0 z-30 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white shadow-sm">
              <LayoutDashboard size={18} />
            </div>
            <h1 className="text-xl font-bold text-gray-800 tracking-tight hidden sm:block">Routine Builder</h1>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1 bg-gray-100 p-1 rounded-xl mr-4 overflow-x-auto">
            <button
              onClick={() => setView('main')}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${
                view === 'main' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:bg-gray-200'
              }`}
            >
              <LayoutDashboard size={14} /> <span className="hidden lg:inline uppercase tracking-widest">Builder</span>
            </button>
            <button
              onClick={() => setView('calendar')}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${
                view === 'calendar' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:bg-gray-200'
              }`}
            >
              <CalendarIcon size={14} /> <span className="hidden lg:inline uppercase tracking-widest">Calendar</span>
            </button>
            <button
              onClick={() => setView('exercises')}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${
                view === 'exercises' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:bg-gray-200'
              }`}
            >
              <BookOpen size={14} /> <span className="hidden lg:inline uppercase tracking-widest">Library</span>
            </button>
            <button
              onClick={() => setView('categories')}
              className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${
                view === 'categories' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:bg-gray-200'
              }`}
            >
              <Tag size={14} /> <span className="hidden lg:inline uppercase tracking-widest">Labels</span>
            </button>
          </div>

          <div className="relative">
            <button 
              onClick={() => setShowProfileMenu(!showProfileMenu)}
              className="w-10 h-10 bg-blue-50 border border-blue-100 rounded-full flex items-center justify-center text-blue-600 font-bold hover:bg-blue-100 transition-colors"
            >
              {user.name.split(' ').map(n => n[0]).join('')}
            </button>

            {showProfileMenu && (
              <div className="absolute right-0 mt-2 w-48 bg-white rounded-2xl shadow-2xl border border-gray-100 p-2 animate-in slide-in-from-top-2 duration-200">
                <div className="px-4 py-3 border-b border-gray-50 mb-1">
                  <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">User Profile</p>
                  <p className="text-sm font-bold text-gray-800 truncate">{user.name}</p>
                </div>
                <button 
                  onClick={handleLogout}
                  className="w-full flex items-center gap-3 px-4 py-2 text-sm text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                >
                  <LogOut size={16} /> Sign Out
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <main className="flex flex-1 overflow-hidden relative">
        {view === 'main' ? (
          <>
            <div 
              className={`flex h-full relative z-20 transition-all duration-300 ease-in-out ${
                isSidebarOpen ? 'w-1/3 min-w-[340px]' : 'w-10 bg-white border-r border-gray-200'
              }`}
            >
              <aside className={`h-full w-full bg-white transition-opacity duration-300 ${isSidebarOpen ? 'opacity-100 border-r border-gray-200' : 'opacity-0 pointer-events-none'}`}>
                <div className="w-full h-full min-w-[340px]">
                  <Sidebar 
                    exercises={exercises} 
                    setExercises={setExercises} 
                    categories={categories}
                  />
                </div>
              </aside>
              <div 
                className={`absolute top-4 z-50 transition-all duration-300 ${isSidebarOpen ? '-right-4' : 'left-1'}`}
              >
                <button 
                  onClick={handleToggleSidebar}
                  className="flex items-center justify-center w-8 h-8 rounded-lg border border-gray-200 bg-white shadow-md text-gray-400 hover:text-blue-600 hover:bg-blue-50 transition-all active:scale-95"
                >
                  {isSidebarOpen ? <ChevronLeft size={20} /> : <Library size={18} />}
                </button>
              </div>
              {!isSidebarOpen && (
                <div 
                  onClick={handleToggleSidebar}
                  className="absolute inset-0 flex flex-col items-center pt-16 cursor-pointer hover:bg-blue-50/50 transition-colors"
                >
                  <div className="flex-1 w-[1px] bg-gray-100 mb-6" />
                  <div className="pb-8 opacity-20 select-none">
                    <p className="text-[9px] font-black tracking-[0.3em] text-gray-900 uppercase rotate-90 origin-center whitespace-nowrap">LIBRARY</p>
                  </div>
                </div>
              )}
            </div>
            <div className="flex-1 overflow-y-auto p-4 sm:p-6 bg-gray-50">
              <div className="max-w-5xl mx-auto">
                <RoutineBuilder 
                  routines={routines} 
                  setRoutines={setRoutines} 
                  exercises={exercises}
                  categories={categories}
                />
              </div>
            </div>
          </>
        ) : view === 'exercises' ? (
          <div className="flex-1 overflow-y-auto p-4 sm:p-6 bg-gray-50">
            <div className="max-w-7xl mx-auto">
              <ExerciseLibrary 
                exercises={exercises}
                setExercises={setExercises}
                categories={categories}
                onPlayVideo={(url) => setActiveVideoUrl(url)}
              />
            </div>
          </div>
        ) : view === 'calendar' ? (
          <CalendarView 
            routines={routines}
            scheduledRoutines={scheduledRoutines}
            setScheduledRoutines={setScheduledRoutines}
            isSidebarOpen={isSidebarOpen}
            setIsSidebarOpen={setIsSidebarOpen}
          />
        ) : (
          <div className="flex-1 overflow-y-auto p-6">
            <div className="max-w-4xl mx-auto">
              <CategoryManager 
                categories={categories} 
                setCategories={setCategories} 
                exercises={exercises}
              />
            </div>
          </div>
        )}
      </main>

      {activeVideoUrl && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl overflow-hidden relative aspect-video">
             <button 
               onClick={() => setActiveVideoUrl(null)}
               className="absolute top-4 right-4 z-20 p-2 bg-black/50 hover:bg-black/80 text-white rounded-full transition-colors shadow-lg"
             >
               <X size={20} />
             </button>
             <iframe
               src={getYoutubeEmbedUrl(activeVideoUrl) || ''}
               className="w-full h-full"
               frameBorder="0"
               allowFullScreen
             />
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { 
  Plus, 
  Edit2, 
  Trash2, 
  Search,
  X,
  Star,
  GripVertical,
  PlayCircle,
  Check
} from 'lucide-react';
import { Exercise, Category } from '../types';

interface SidebarProps {
  exercises: Exercise[];
  setExercises: React.Dispatch<React.SetStateAction<Exercise[]>>;
  categories: Category[];
}

const getYoutubeEmbedUrl = (url: string) => {
  const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
  const match = url.match(regExp);
  const id = (match && match[2].length === 11) ? match[2] : null;
  if (!id) return null;
  return `https://www.youtube.com/embed/${id}?rel=0&modestbranding=1&enablejsapi=1`;
};

const Sidebar: React.FC<SidebarProps> = ({ exercises, setExercises, categories }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [expandedVideoId, setExpandedVideoId] = useState<number | null>(null);

  const [formData, setFormData] = useState<Partial<Exercise>>({
    title: '',
    description: '',
    categories: [],
    videoUrl: '',
    rating: 0
  });

  const resetForm = () => {
    setFormData({
      title: '',
      description: '',
      categories: [],
      videoUrl: '',
      rating: 0
    });
    setEditingId(null);
    setShowAddForm(false);
  };

  const handleSave = () => {
    if (!formData.title?.trim()) return;

    const finalData: Exercise = {
      id: editingId || Date.now(),
      title: formData.title || '',
      description: formData.description || '',
      categories: formData.categories || [],
      videoUrl: formData.videoUrl || '',
      rating: formData.rating || 0,
    };

    if (editingId) {
      setExercises(prev => prev.map(ex => ex.id === editingId ? finalData : ex));
    } else {
      setExercises(prev => [...prev, finalData]);
    }
    resetForm();
  };

  const handleEdit = (ex: Exercise) => {
    setEditingId(ex.id);
    setFormData({ ...ex });
    setShowAddForm(true);
  };

  const handleDelete = (id: number) => {
    if (confirm("Delete this exercise from library?")) {
      setExercises(prev => prev.filter(e => e.id !== id));
    }
  };

  const toggleCategorySelection = (catName: string) => {
    setFormData(prev => {
      const currentCats = prev.categories || [];
      const newCats = currentCats.includes(catName)
        ? currentCats.filter(c => c !== catName)
        : [...currentCats, catName];
      return { ...prev, categories: newCats };
    });
  };

  const filteredExercises = exercises.filter(ex => 
    ex.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    ex.categories.some(cat => cat.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const grouped = categories.map(cat => ({
    category: cat,
    items: filteredExercises.filter(ex => ex.categories.includes(cat.name))
  })).filter(g => g.items.length > 0);

  const StarRating = ({ rating, onRate }: { rating: number; onRate: (r: number) => void }) => (
    <div className="flex gap-1">
      {[1, 2, 3, 4, 5].map(star => (
        <button
          key={star}
          onClick={() => onRate(star)}
          className={`transition-colors ${rating >= star ? 'text-yellow-400' : 'text-gray-300'}`}
        >
          <Star size={16} fill={rating >= star ? 'currentColor' : 'none'} />
        </button>
      ))}
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-white border-r border-gray-100">
      <div className="p-5 border-b border-gray-50 bg-gray-50/30">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-lg font-bold text-gray-800">Exercise Library</h2>
          <button 
            onClick={() => setShowAddForm(true)}
            className="flex items-center gap-1 px-3 py-1.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-all shadow-sm text-sm"
          >
            <Plus size={16} /> <span>New</span>
          </button>
        </div>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
          <input 
            type="text" 
            placeholder="Search exercises..." 
            className="w-full pl-10 pr-4 py-2 bg-white border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 shadow-sm"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        {/* "Add New" button in search bar */}
        {searchTerm.trim().length > 0 && (
          <button
            onClick={() => {
              setFormData({ ...formData, title: searchTerm, categories: [] });
              setShowAddForm(true);
            }}
            className="w-full mt-3 flex items-center justify-center gap-2 py-2 border-2 border-dashed border-blue-200 text-blue-600 rounded-xl text-xs font-bold hover:bg-blue-50 transition-all animate-in slide-in-from-top-1"
          >
            <Plus size={14} /> Create "{searchTerm}"
          </button>
        )}
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        {showAddForm && (
          <div className="p-4 bg-gray-50 rounded-xl border border-gray-200 shadow-sm space-y-4 relative animate-in fade-in slide-in-from-top-2 duration-200">
            <button onClick={resetForm} className="absolute top-2 right-2 text-gray-400 hover:text-gray-600">
              <X size={16} />
            </button>
            <h3 className="font-bold text-gray-800 text-sm">{editingId ? 'Update Exercise' : 'Create Exercise'}</h3>

            <div className="space-y-3">
              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Title</label>
                <input 
                  type="text" 
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500"
                  value={formData.title}
                  onChange={e => setFormData({...formData, title: e.target.value})}
                  placeholder="e.g. Chin Tuck Hold"
                />
              </div>

              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-2">Categories (Select Multiple)</label>
                <div className="flex flex-wrap gap-1.5 p-2 bg-white border border-gray-100 rounded-lg max-h-32 overflow-y-auto">
                  {categories.map(c => {
                    const isSelected = formData.categories?.includes(c.name);
                    return (
                      <button
                        key={c.name}
                        onClick={() => toggleCategorySelection(c.name)}
                        className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold transition-all border ${isSelected ? 'bg-blue-600 text-white border-blue-600' : 'bg-gray-50 text-gray-500 border-gray-100 hover:border-blue-200'}`}
                      >
                        <div className={`w-1.5 h-1.5 rounded-full ${isSelected ? 'bg-white' : c.color}`} />
                        {c.name}
                        {isSelected && <Check size={10} />}
                      </button>
                    );
                  })}
                </div>
              </div>

              <div className="flex justify-between items-center">
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider">Rating</label>
                <StarRating rating={formData.rating || 0} onRate={r => setFormData({...formData, rating: r})} />
              </div>

              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Description</label>
                <textarea 
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500"
                  rows={2}
                  value={formData.description}
                  onChange={e => setFormData({...formData, description: e.target.value})}
                  placeholder="Instructions..."
                />
              </div>

              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">YouTube Link</label>
                <input 
                  type="text" 
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500"
                  value={formData.videoUrl}
                  onChange={e => setFormData({...formData, videoUrl: e.target.value})}
                  placeholder="Paste URL..."
                />
              </div>
            </div>

            <div className="flex gap-2 pt-2">
              <button 
                onClick={handleSave}
                className="flex-1 py-2 bg-blue-600 text-white rounded-lg text-sm font-semibold hover:bg-blue-700 shadow-sm"
              >
                {editingId ? 'Save Changes' : 'Add to Library'}
              </button>
            </div>
          </div>
        )}

        {grouped.length === 0 ? (
          <div className="text-center py-10">
            <p className="text-gray-400 text-sm">No exercises found.</p>
          </div>
        ) : (
          grouped.map(({ category, items }) => (
            <div key={category.name} className="space-y-2">
              <div className="flex items-center gap-2 px-1">
                <div className={`w-2 h-2 rounded-full ${category.color}`} />
                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest">{category.name}</h4>
              </div>
              <div className="space-y-1.5">
                {items.map(ex => {
                  const embedUrl = ex.videoUrl ? getYoutubeEmbedUrl(ex.videoUrl) : null;
                  const isExpanded = expandedVideoId === ex.id;

                  return (
                    <div 
                      key={ex.id}
                      draggable
                      onDragStart={(e) => {
                        e.dataTransfer.setData('exerciseId', ex.id.toString());
                      }}
                      className="group flex flex-col bg-white border border-gray-100 rounded-xl hover:border-blue-200 hover:shadow-md transition-all"
                    >
                      <div className="flex items-center gap-2 p-3">
                        <GripVertical size={16} className="text-gray-300 group-hover:text-blue-400 transition-colors cursor-grab active:cursor-grabbing" />
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-1.5">
                            <p className="text-sm font-semibold text-gray-700 truncate">{ex.title}</p>
                            {embedUrl && (
                              <button 
                                onClick={() => setExpandedVideoId(isExpanded ? null : ex.id)}
                                className={`transition-colors ${isExpanded ? 'text-blue-700' : 'text-blue-500 hover:text-blue-700'}`}
                              >
                                <PlayCircle size={14} />
                              </button>
                            )}
                          </div>
                          <div className="flex flex-wrap gap-1 mt-1">
                            {ex.categories.map(c => {
                              const catInfo = categories.find(ci => ci.name === c);
                              return (
                                <div key={c} className={`w-1.5 h-1.5 rounded-full ${catInfo?.color || 'bg-gray-300'}`} title={c} />
                              );
                            })}
                          </div>
                        </div>
                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => handleEdit(ex)}
                            className="p-1.5 hover:bg-gray-100 rounded-lg text-gray-400 hover:text-blue-500"
                          >
                            <Edit2 size={14} />
                          </button>
                          <button 
                            onClick={() => handleDelete(ex.id)}
                            className="p-1.5 hover:bg-red-50 rounded-lg text-gray-400 hover:text-red-500"
                          >
                            <Trash2 size={14} />
                          </button>
                        </div>
                      </div>

                      {isExpanded && embedUrl && (
                        <div className="px-3 pb-3 pt-0 animate-in slide-in-from-top-2 duration-200">
                          <div className="relative aspect-video w-full rounded-lg overflow-hidden bg-black border border-gray-200">
                            <iframe
                              src={embedUrl}
                              className="w-full h-full"
                              frameBorder="0"
                              allowFullScreen
                            />
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

