### Database Setup Instructions

To make this code work, go to your **Supabase Dashboard**, open the **SQL Editor**, and run the following script to create the tables:

```sql
-- Create Exercises Table
create table exercises (
  id bigint primary key,
  user_id uuid references auth.users not null default auth.uid(),
  title text not null,
  description text,
  categories text[] default '{}',
  video_url text,
  rating int default 0,
  created_at timestamp with time zone default now()
);

-- Create Routines Table
create table routines (
  id bigint primary key,
  user_id uuid references auth.users not null default auth.uid(),
  name text not null,
  exercise_items jsonb default '[]',
  sub_routines jsonb default '[]',
  is_expanded boolean default true,
  order_index int default 0,
  created_at timestamp with time zone default now()
);

-- Create Categories Table
create table categories (
  id uuid default gen_random_uuid() primary key,
  user_id uuid references auth.users not null default auth.uid(),
  name text not null,
  color text not null,
  created_at timestamp with time zone default now()
);

-- Create Scheduled Routines Table
create table scheduled_routines (
  id text primary key,
  user_id uuid references auth.users not null default auth.uid(),
  routine_id bigint,
  date date not null,
  duration int,
  recurrence text,
  created_at timestamp with time zone default now()
);

-- Enable Row Level Security (RLS)
alter table exercises enable row level security;
alter table routines enable row level security;
alter table categories enable row level security;
alter table scheduled_routines enable row level security;

-- Create Policies (Example for exercises, repeat for others)
create policy "Users can only access their own exercises" on exercises for all using (auth.uid() = user_id);
create policy "Users can only access their own routines" on routines for all using (auth.uid() = user_id);
create policy "Users can only access their own categories" on categories for all using (auth.uid() = user_id);
create policy "Users can only access their own schedules" on scheduled_routines for all using (auth.uid() = user_id);

