import React, { useState, useEffect, useRef } from 'react';
import { 
  Tag, 
  LayoutDashboard,
  BookOpen,
  ChevronLeft,
  Library,
  X,
  User as UserIcon,
  Calendar as CalendarIcon,
  Database,
  Monitor,
  RefreshCw,
  Loader2,
  HardDrive
} from 'lucide-react';
import { Exercise, Routine, Category, ViewType, User, ScheduledRoutine } from './types.ts';
import { DEFAULT_CATEGORIES } from './constants.tsx';
import Sidebar from './components/Sidebar.tsx';
import RoutineBuilder from './components/RoutineBuilder.tsx';
import ExerciseLibrary from './components/ExerciseLibrary.tsx';
import CalendarView from './components/CalendarView.tsx';
import DataManagement from './components/DataManagement.tsx';

// Mock user for local-only mode
const LOCAL_USER: User = {
  id: 'local-device-user',
  email: 'local@device',
  name: 'User'
};

export default function App() {
  const [user, setUser] = useState<User | null>(LOCAL_USER);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSynced, setLastSynced] = useState<Date | null>(null);

  const [view, setView] = useState<ViewType>('main');
  const [exercises, setExercises] = useState<Exercise[]>([]);
  const [routines, setRoutines] = useState<Routine[]>([]);
  const [scheduledRoutines, setScheduledRoutines] = useState<ScheduledRoutine[]>([]);
  const [categories, setCategories] = useState<Category[]>(DEFAULT_CATEGORIES);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [activeVideoUrl, setActiveVideoUrl] = useState<string | null>(null);
  const [showProfileMenu, setShowProfileMenu] = useState(false);

  const initialLoadRef = useRef(false);

  // Load Data from Local Storage on Start
  useEffect(() => {
    const loadData = () => {
      try {
        const savedExercises = localStorage.getItem('necktrack_exercises');
        const savedRoutines = localStorage.getItem('necktrack_routines');
        const savedSchedules = localStorage.getItem('necktrack_schedules');
        const savedCategories = localStorage.getItem('necktrack_categories');

        if (savedExercises) setExercises(JSON.parse(savedExercises));
        if (savedRoutines) setRoutines(JSON.parse(savedRoutines));
        if (savedSchedules) setScheduledRoutines(JSON.parse(savedSchedules));
        if (savedCategories) setCategories(JSON.parse(savedCategories));

        setLastSynced(new Date());
        initialLoadRef.current = true;
      } catch (e) {
        console.error("Local storage load error", e);
      }
    };

    loadData();
  }, []);

  // Sync Data to Local Storage (Auto-save)
  useEffect(() => {
    if (!initialLoadRef.current) return;

    const syncToLocal = () => {
      setIsSyncing(true);
      try {
        localStorage.setItem('necktrack_exercises', JSON.stringify(exercises));
        localStorage.setItem('necktrack_routines', JSON.stringify(routines));
        localStorage.setItem('necktrack_schedules', JSON.stringify(scheduledRoutines));
        localStorage.setItem('necktrack_categories', JSON.stringify(categories));
        setLastSynced(new Date());
      } catch (e) {
        console.error("Local storage save error", e);
      } finally {
        setTimeout(() => setIsSyncing(false), 300);
      }
    };

    const debounceTimer = setTimeout(syncToLocal, 500);
    return () => clearTimeout(debounceTimer);
  }, [exercises, routines, scheduledRoutines, categories]);

  const getYoutubeEmbedUrl = (url: string) => {
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    const id = (match && match[2].length === 11) ? match[2] : null;
    return id ? `https://www.youtube.com/embed/${id}?rel=0&modestbranding=1&enablejsapi=1` : null;
  };

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-50 text-gray-900 font-sans">
      <header className="bg-white border-b px-6 py-3 flex items-center justify-between flex-shrink-0 z-30 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white shadow-sm">
              <LayoutDashboard size={18} />
            </div>
            <h1 className="text-xl font-bold text-gray-800 tracking-tight hidden sm:block">NeckTrack</h1>
          </div>

          <div className="flex items-center gap-2">
            {isSyncing ? (
              <div className="flex items-center gap-2 text-blue-500 text-[10px] font-black uppercase tracking-widest bg-blue-50 px-3 py-1 rounded-full animate-pulse">
                <RefreshCw size={10} className="animate-spin" /> Saving...
              </div>
            ) : lastSynced && (
              <div className="flex items-center gap-2 text-gray-500 text-[10px] font-black uppercase tracking-widest bg-gray-100 px-3 py-1 rounded-full">
                <HardDrive size={10} /> Local Storage
              </div>
            )}
          </div>
        </div>

        <div className="flex items-center gap-2">
          <div className="flex items-center gap-1 bg-gray-100 p-1 rounded-xl mr-4 overflow-x-auto max-w-[50vw]">
            {[
              { id: 'main', icon: LayoutDashboard, label: 'Builder' },
              { id: 'calendar', icon: CalendarIcon, label: 'Calendar' },
              { id: 'exercises', icon: BookOpen, label: 'Library' },
              { id: 'data', icon: Database, label: 'Backup' }
            ].map((nav) => (
              <button
                key={nav.id}
                onClick={() => setView(nav.id as ViewType)}
                className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${
                  view === nav.id ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:bg-gray-200'
                }`}
              >
                <nav.icon size={14} /> <span className="hidden lg:inline uppercase tracking-widest">{nav.label}</span>
              </button>
            ))}
          </div>

          <div className="relative">
            <button 
              onClick={() => setShowProfileMenu(!showProfileMenu)}
              className="w-10 h-10 bg-blue-50 border border-blue-100 rounded-full flex items-center justify-center text-blue-600 font-bold hover:bg-blue-100 transition-colors uppercase flex-shrink-0"
            >
              <UserIcon size={18} />
            </button>
            {showProfileMenu && (
              <div className="absolute right-0 mt-2 w-56 bg-white border border-gray-100 rounded-2xl shadow-2xl py-2 z-50 animate-in fade-in zoom-in-95">
                <div className="px-4 py-3 border-b border-gray-50 mb-1">
                  <p className="text-xs font-black text-gray-400 uppercase tracking-widest">Storage Status</p>
                  <p className="text-sm font-bold text-gray-800 truncate">Device Session</p>
                  <p className="text-[10px] text-gray-500">Data is stored locally on this browser.</p>
                </div>
                <button 
                  onClick={() => setShowProfileMenu(false)}
                  className="w-full flex items-center gap-3 px-4 py-2.5 text-sm font-semibold text-gray-600 hover:bg-gray-50 transition-colors"
                >
                  <Monitor size={16} /> Dashboard
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      <main className="flex flex-1 overflow-hidden relative">
        {view === 'main' ? (
          <>
            <div className={`flex h-full relative z-20 transition-all duration-300 ease-in-out ${isSidebarOpen ? 'w-1/3 min-w-[340px]' : 'w-10 bg-white border-r border-gray-200'}`}>
              <aside className={`h-full w-full bg-white transition-opacity duration-300 ${isSidebarOpen ? 'opacity-100 border-r border-gray-200' : 'opacity-0 pointer-events-none'}`}>
                <div className="w-full h-full min-w-[340px]">
                  <Sidebar exercises={exercises} setExercises={setExercises} categories={categories} />
                </div>
              </aside>
              <div className={`absolute top-4 z-50 transition-all duration-300 ${isSidebarOpen ? '-right-4' : 'left-1'}`}>
                <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="flex items-center justify-center w-8 h-8 rounded-lg border border-gray-200 bg-white shadow-md text-gray-400 hover:text-blue-600 hover:bg-blue-50 transition-all">
                  {isSidebarOpen ? <ChevronLeft size={20} /> : <Library size={18} />}
                </button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-4 sm:p-6 bg-gray-50">
              <div className="max-w-5xl mx-auto">
                <RoutineBuilder 
                  routines={routines} 
                  setRoutines={setRoutines} 
                  exercises={exercises}
                  setExercises={setExercises}
                  categories={categories}
                />
              </div>
            </div>
          </>
        ) : view === 'exercises' ? (
          <div className="flex-1 overflow-y-auto p-4 sm:p-6 bg-gray-50">
            <div className="max-w-7xl mx-auto">
              <ExerciseLibrary 
                exercises={exercises} 
                setExercises={setExercises} 
                categories={categories} 
                setCategories={setCategories}
                onPlayVideo={setActiveVideoUrl} 
              />
            </div>
          </div>
        ) : view === 'calendar' ? (
          <CalendarView routines={routines} scheduledRoutines={scheduledRoutines} setScheduledRoutines={setScheduledRoutines} isSidebarOpen={isSidebarOpen} setIsSidebarOpen={setIsSidebarOpen} />
        ) : (
          <div className="flex-1 overflow-y-auto p-4 sm:p-6 bg-gray-50">
            <div className="max-w-4xl mx-auto">
              <DataManagement 
                exercises={exercises} 
                setExercises={setExercises}
                routines={routines}
                setRoutines={setRoutines}
                categories={categories}
                setCategories={setCategories}
                scheduledRoutines={scheduledRoutines}
                setScheduledRoutines={setScheduledRoutines}
              />
            </div>
          </div>
        )}
      </main>

      {activeVideoUrl && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl overflow-hidden relative aspect-video">
             <button onClick={() => setActiveVideoUrl(null)} className="absolute top-4 right-4 z-20 p-2 bg-black/50 hover:bg-black/80 text-white rounded-full transition-colors shadow-lg">
               <X size={20} />
             </button>
             <iframe src={getYoutubeEmbedUrl(activeVideoUrl) || ''} className="w-full h-full" frameBorder="0" allowFullScreen />
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { 
  Plus, 
  Search, 
  ChevronDown, 
  ChevronRight, 
  Edit2, 
  Trash2, 
  Star,
  PlayCircle,
  X,
  Check,
  PlusCircle,
  FolderPlus,
  Tag
} from 'lucide-react';
import { Exercise, Category } from '../types';
import { COLORS } from '../constants';

interface ExerciseLibraryProps {
  exercises: Exercise[];
  setExercises: React.Dispatch<React.SetStateAction<Exercise[]>>;
  categories: Category[];
  setCategories: React.Dispatch<React.SetStateAction<Category[]>>;
  onPlayVideo: (url: string) => void;
}

const ExerciseLibrary: React.FC<ExerciseLibraryProps> = ({ 
  exercises, 
  setExercises, 
  categories, 
  setCategories,
  onPlayVideo 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [collapsedCategories, setCollapsedCategories] = useState<Set<string>>(new Set());
  const [editingEx, setEditingEx] = useState<Exercise | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);

  // New Category States
  const [showNewCatForm, setShowNewCatForm] = useState(false);
  const [newCatName, setNewCatName] = useState('');
  const [selectedCatColor, setSelectedCatColor] = useState(COLORS[0]);

  const toggleCategory = (catName: string) => {
    const newCollapsed = new Set(collapsedCategories);
    if (newCollapsed.has(catName)) {
      newCollapsed.delete(catName);
    } else {
      newCollapsed.add(catName);
    }
    setCollapsedCategories(newCollapsed);
  };

  const handleDelete = (id: number) => {
    if (confirm("Permanently delete this exercise?")) {
      setExercises(prev => prev.filter(e => e.id !== id));
    }
  };

  const handleEdit = (ex: Exercise) => {
    setEditingEx(ex);
    setShowAddForm(true);
  };

  const handleAddNewToCategory = (catName: string) => {
    setEditingEx({
      id: 0,
      title: '',
      description: '',
      categories: [catName],
      videoUrl: '',
      rating: 0
    });
    setShowAddForm(true);
  };

  const handleCreateCategory = () => {
    if (!newCatName.trim()) return;
    if (categories.some(c => c.name.toLowerCase() === newCatName.trim().toLowerCase())) {
      alert("A category with this name already exists.");
      return;
    }
    setCategories(prev => [...prev, { name: newCatName.trim(), color: selectedCatColor }]);
    setNewCatName('');
    setShowNewCatForm(false);
  };

  const handleDeleteCategory = (catName: string) => {
    const usage = exercises.filter(ex => ex.categories.includes(catName)).length;
    if (usage > 0) {
      alert(`Cannot delete "${catName}" because it contains ${usage} exercise(s). Move or delete them first.`);
      return;
    }
    if (confirm(`Delete the "${catName}" category?`)) {
      setCategories(prev => prev.filter(c => c.name !== catName));
    }
  };

  const filteredExercises = exercises.filter(ex => 
    ex.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    ex.categories.some(c => c.toLowerCase().includes(searchTerm.toLowerCase())) ||
    ex.description.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const groups = categories.map(cat => ({
    category: cat,
    items: filteredExercises.filter(ex => ex.categories.includes(cat.name))
  })).filter(g => g.items.length > 0 || searchTerm === '');

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-2xl border border-gray-200 shadow-sm">
        <div>
          <h2 className="text-2xl font-bold text-gray-800">Exercise Library</h2>
          <p className="text-gray-500">View and manage your entire exercise catalog</p>
        </div>
        <div className="flex flex-col gap-3">
          <div className="flex items-center gap-3">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
              <input 
                type="text" 
                placeholder="Search exercises..." 
                className="pl-10 pr-4 py-2 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none w-full md:w-64"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
              />
            </div>
            <button 
              onClick={() => { setEditingEx(null); setShowAddForm(true); }}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-md transition-all whitespace-nowrap"
            >
              <Plus size={20} /> Add New
            </button>
          </div>
        </div>
      </div>

      {showAddForm && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-gray-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between p-6 border-b">
              <h3 className="text-xl font-bold text-gray-800">{editingEx && editingEx.id !== 0 ? 'Edit Exercise' : 'Create Exercise'}</h3>
              <button onClick={() => setShowAddForm(false)} className="text-gray-400 hover:text-gray-600"><X size={24} /></button>
            </div>
            <div className="p-6 space-y-4">
              <ExerciseForm 
                initialData={editingEx || undefined} 
                categories={categories} 
                onSave={(data) => {
                  if (editingEx && editingEx.id !== 0) {
                    setExercises(prev => prev.map(ex => ex.id === editingEx.id ? { ...ex, ...data } as Exercise : ex));
                  } else {
                    setExercises(prev => [...prev, { ...data, id: Date.now() } as Exercise]);
                  }
                  setShowAddForm(false);
                }}
                onCancel={() => setShowAddForm(false)}
              />
            </div>
          </div>
        </div>
      )}

      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3 items-start">
        {groups.map(({ category, items }) => (
          <div 
            key={category.name} 
            className="bg-white rounded-2xl border border-gray-200 shadow-sm flex flex-col overflow-hidden group/cat"
          >
            <div className={`h-2 w-full ${category.color}`} />
            <div className="flex items-center justify-between bg-gray-50/50 hover:bg-gray-100 transition-colors">
              <button 
                onClick={() => toggleCategory(category.name)}
                className="flex flex-1 items-center gap-3 p-4 text-left"
              >
                <span className={`w-3 h-3 rounded-full ${category.color}`} />
                <h3 className="font-bold text-gray-700">{category.name}</h3>
                <span className="text-xs font-bold text-gray-400 bg-gray-200/50 px-2 py-0.5 rounded-full">{items.length}</span>
                {collapsedCategories.has(category.name) ? <ChevronRight size={18} className="text-gray-400 ml-auto" /> : <ChevronDown size={18} className="text-gray-400 ml-auto" />}
              </button>
              <div className="flex items-center mr-2">
                <button 
                  onClick={() => handleAddNewToCategory(category.name)}
                  title={`Add exercise to ${category.name}`}
                  className="p-2 text-blue-500 hover:text-blue-700 hover:bg-blue-50 rounded-lg transition-colors"
                >
                  <PlusCircle size={20} />
                </button>
                <button 
                  onClick={() => handleDeleteCategory(category.name)}
                  className="p-2 text-gray-300 hover:text-red-500 opacity-0 group-hover/cat:opacity-100 transition-opacity"
                  title="Delete category"
                >
                  <Trash2 size={16} />
                </button>
              </div>
            </div>

            {!collapsedCategories.has(category.name) && (
              <div className="p-3 space-y-3 min-h-[50px] bg-white animate-in slide-in-from-top-2 duration-200">
                {items.length === 0 ? (
                  <p className="text-center py-6 text-xs text-gray-400 italic">No exercises here</p>
                ) : (
                  items.map(ex => (
                    <div 
                      key={ex.id} 
                      onClick={() => ex.videoUrl && onPlayVideo(ex.videoUrl)}
                      className={`group/ex p-4 bg-gray-50 rounded-xl border border-transparent hover:border-blue-200 hover:bg-blue-50/30 transition-all ${ex.videoUrl ? 'cursor-pointer' : ''}`}
                    >
                      <div className="flex items-start justify-between gap-2 mb-2">
                        <div className="flex flex-col gap-1">
