                key={c.name}
                onClick={() => toggleCategory(c.name)}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all border ${isSelected ? 'bg-blue-600 text-white border-blue-600' : 'bg-gray-50 text-gray-500 border-gray-100 hover:border-blue-200'}`}
              >
                <div className={`w-1.5 h-1.5 rounded-full ${isSelected ? 'bg-white' : c.color}`} />
                {c.name}
                {isSelected && <Check size={10} />}
              </button>
            );
          })}
        </div>
      </div>

      <div className="flex justify-between items-center">
        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest">Rating</label>
        <div className="flex items-center">
          {[1,2,3,4,5].map(r => (
            <button 
              key={r} 
              onClick={() => setFormData({ ...formData, rating: r })}
              className={`p-1 ${r <= (formData.rating || 0) ? 'text-yellow-400' : 'text-gray-200'}`}
            >
              <Star size={20} fill={r <= (formData.rating || 0) ? 'currentColor' : 'none'} />
            </button>
          ))}
        </div>
      </div>

      <div>
        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1">Description</label>
        <textarea 
          value={formData.description} 
          onChange={e => setFormData({ ...formData, description: e.target.value })}
          className="w-full px-4 py-3 border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
          rows={3}
          placeholder="Step by step instructions..."
        />
      </div>
      <div>
        <label className="block text-xs font-bold text-gray-400 uppercase tracking-widest mb-1">Video Link (YouTube)</label>
        <input 
          type="text" 
          value={formData.videoUrl} 
          onChange={e => setFormData({ ...formData, videoUrl: e.target.value })}
          className="w-full px-4 py-3 border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
          placeholder="YouTube URL..."
        />
      </div>
      <div className="flex gap-2 pt-4">
        <button 
          onClick={() => onSave(formData)}
          className="flex-1 py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-md"
        >
          {initialData && initialData.id !== 0 ? 'Update Exercise' : 'Save Exercise'}
        </button>
        <button 
          onClick={onCancel}
          className="px-6 py-3 bg-gray-100 text-gray-600 rounded-xl font-bold hover:bg-gray-200"
        >
          Cancel
        </button>
      </div>
    </div>
  );
};

export default ExerciseLibrary;

import React, { useState } from 'react';
import { 
  Plus, 
  Edit2, 
  Trash2, 
  Search,
  X,
  Star,
  GripVertical,
  PlayCircle,
  Check,
  PlusCircle
} from 'lucide-react';
import { Exercise, Category } from '../types';

interface SidebarProps {
  exercises: Exercise[];
  setExercises: React.Dispatch<React.SetStateAction<Exercise[]>>;
  categories: Category[];
}

const getYoutubeEmbedUrl = (url: string) => {
  const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
  const match = url.match(regExp);
  const id = (match && match[2].length === 11) ? match[2] : null;
  if (!id) return null;
  return `https://www.youtube.com/embed/${id}?rel=0&modestbranding=1&enablejsapi=1`;
};

const Sidebar: React.FC<SidebarProps> = ({ exercises, setExercises, categories }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [expandedVideoId, setExpandedVideoId] = useState<number | null>(null);

  const [formData, setFormData] = useState<Partial<Exercise>>({
    title: '',
    description: '',
    categories: [],
    videoUrl: '',
    rating: 0
  });

  const resetForm = () => {
    setFormData({
      title: '',
      description: '',
      categories: [],
      videoUrl: '',
      rating: 0
    });
    setEditingId(null);
    setShowAddForm(false);
  };

  const handleSave = () => {
    if (!formData.title?.trim()) return;

    const finalData: Exercise = {
      id: editingId || Date.now(),
      title: formData.title || '',
      description: formData.description || '',
      categories: formData.categories || [],
      videoUrl: formData.videoUrl || '',
      rating: formData.rating || 0,
    };

    if (editingId) {
      setExercises(prev => prev.map(ex => ex.id === editingId ? finalData : ex));
    } else {
      setExercises(prev => [...prev, finalData]);
    }
    resetForm();
  };

  const handleEdit = (ex: Exercise) => {
    setEditingId(ex.id);
    setFormData({ ...ex });
    setShowAddForm(true);
  };

  const handleDelete = (id: number) => {
    if (confirm("Delete this exercise from library?")) {
      setExercises(prev => prev.filter(e => e.id !== id));
    }
  };

  const toggleCategorySelection = (catName: string) => {
    setFormData(prev => {
      const currentCats = prev.categories || [];
      const newCats = currentCats.includes(catName)
        ? currentCats.filter(c => c !== catName)
        : [...currentCats, catName];
      return { ...prev, categories: newCats };
    });
  };

  const handleAddNewToCategory = (catName: string) => {
    setFormData({
      title: '',
      description: '',
      categories: [catName],
      videoUrl: '',
      rating: 0
    });
    setEditingId(null);
    setShowAddForm(true);
  };

  const filteredExercises = exercises.filter(ex => 
    ex.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    ex.categories.some(cat => cat.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  // Group and Sort logic for consistency with Main Library
  const grouped = categories.map(cat => ({
    category: cat,
    items: filteredExercises.filter(ex => ex.categories.includes(cat.name))
  })).sort((a, b) => {
    // Primary sort: Count (descending)
    if (b.items.length !== a.items.length) {
      return b.items.length - a.items.length;
    }
    // Secondary sort: Alphabetical
    return a.category.name.localeCompare(b.category.name);
  }).filter(g => g.items.length > 0 || (searchTerm === '' && g.items.length >= 0)); 
  // We keep showing all categories in sidebar if search is empty, but sorted

  const StarRating = ({ rating, onRate }: { rating: number; onRate: (r: number) => void }) => (
    <div className="flex gap-1">
      {[1, 2, 3, 4, 5].map(star => (
        <button
          key={star}
          onClick={() => onRate(star)}
          className={`transition-colors ${rating >= star ? 'text-yellow-400' : 'text-gray-300'}`}
        >
          <Star size={16} fill={rating >= star ? 'currentColor' : 'none'} />
        </button>
      ))}
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-white border-r border-gray-100">
      <div className="p-5 border-b border-gray-50 bg-gray-50/30">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-lg font-bold text-gray-800">Exercise Library</h2>
          <button 
            onClick={() => setShowAddForm(true)}
            className="flex items-center gap-1 px-3 py-1.5 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-all shadow-sm text-sm"
          >
            <Plus size={16} /> <span>New</span>
          </button>
        </div>

        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
          <input 
            type="text" 
            placeholder="Search exercises..." 
            className="w-full pl-10 pr-4 py-2 bg-white border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 shadow-sm"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6">
        {showAddForm && (
          <div className="p-4 bg-gray-50 rounded-xl border border-gray-200 shadow-sm space-y-4 relative animate-in fade-in slide-in-from-top-2 duration-200">
            <button onClick={resetForm} className="absolute top-2 right-2 text-gray-400 hover:text-gray-600">
              <X size={16} />
            </button>
            <h3 className="font-bold text-gray-800 text-sm">{editingId ? 'Update Exercise' : 'Create Exercise'}</h3>

            <div className="space-y-3">
              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Title</label>
                <input 
                  type="text" 
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500"
                  value={formData.title}
                  onChange={e => setFormData({...formData, title: e.target.value})}
                  placeholder="e.g. Chin Tuck Hold"
                  autoFocus
                />
              </div>

              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-2">Categories</label>
                <div className="flex flex-wrap gap-1.5 p-2 bg-white border border-gray-100 rounded-lg max-h-32 overflow-y-auto">
                  {categories.map(c => {
                    const isSelected = formData.categories?.includes(c.name);
                    return (
                      <button
                        key={c.name}
                        onClick={() => toggleCategorySelection(c.name)}
                        className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold transition-all border ${isSelected ? 'bg-blue-600 text-white border-blue-600' : 'bg-gray-50 text-gray-500 border-gray-100 hover:border-blue-200'}`}
                      >
                        <div className={`w-1.5 h-1.5 rounded-full ${isSelected ? 'bg-white' : c.color}`} />
                        {c.name}
                        {isSelected && <Check size={10} />}
                      </button>
                    );
                  })}
                </div>
              </div>

              <div className="flex justify-between items-center">
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider">Rating</label>
                <StarRating rating={formData.rating || 0} onRate={r => setFormData({...formData, rating: r})} />
              </div>

              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Description</label>
                <textarea 
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500"
                  rows={2}
                  value={formData.description}
                  onChange={e => setFormData({...formData, description: e.target.value})}
                  placeholder="Instructions..."
                />
              </div>

              <div>
                <label className="block text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">YouTube Link</label>
                <input 
                  type="text" 
                  className="w-full px-3 py-2 text-sm border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500"
                  value={formData.videoUrl}
                  onChange={e => setFormData({...formData, videoUrl: e.target.value})}
                  placeholder="Paste URL..."
                />
              </div>
            </div>

            <div className="flex gap-2 pt-2">
              <button 
                onClick={handleSave}
                className="flex-1 py-2 bg-blue-600 text-white rounded-lg text-sm font-semibold hover:bg-blue-700 shadow-sm"
              >
                {editingId ? 'Save Changes' : 'Add to Library'}
              </button>
            </div>
          </div>
        )}

        {grouped.length === 0 ? (
          <div className="text-center py-10">
            <p className="text-gray-400 text-sm">No exercises found.</p>
          </div>
        ) : (
          grouped.map(({ category, items }) => (
            <div key={category.name} className="space-y-2">
              <div className="flex items-center justify-between px-1">
                <div className="flex items-center gap-2 overflow-hidden">
                  <div className={`w-2 h-2 rounded-full shrink-0 ${category.color}`} />
                  <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest truncate">
                    {category.name} 
                    <span className="ml-2 text-blue-400">({items.length})</span>
                  </h4>
                </div>
                <button 
                  onClick={() => handleAddNewToCategory(category.name)}
                  className="text-blue-500 hover:text-blue-700 p-1 rounded-md hover:bg-blue-50 transition-all shrink-0"
                  title={`Quick add to ${category.name}`}
                >
                  <PlusCircle size={14} />
                </button>
              </div>
              <div className="space-y-1.5">
                {items.map(ex => {
                  const embedUrl = ex.videoUrl ? getYoutubeEmbedUrl(ex.videoUrl) : null;
                  const isExpanded = expandedVideoId === ex.id;

                  return (
                    <div 
                      key={ex.id}
                      draggable
                      onDragStart={(e) => {
                        e.dataTransfer.setData('exerciseId', ex.id.toString());
                      }}
                      className="group flex flex-col bg-white border border-gray-100 rounded-xl hover:border-blue-200 hover:shadow-md transition-all"
                    >
                      <div className="flex items-center gap-2 p-3">
                        <GripVertical size={16} className="text-gray-300 group-hover:text-blue-400 transition-colors cursor-grab active:cursor-grabbing" />
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-1.5">
                            <p className="text-sm font-semibold text-gray-700 truncate">{ex.title}</p>
                            {embedUrl && (
                              <button 
                                onClick={() => setExpandedVideoId(isExpanded ? null : ex.id)}
                                className={`transition-colors ${isExpanded ? 'text-blue-700' : 'text-blue-500 hover:text-blue-700'}`}
                              >
                                <PlayCircle size={14} />
                              </button>
                            )}
                          </div>
                        </div>
                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => handleEdit(ex)}
                            className="p-1.5 hover:bg-gray-100 rounded-lg text-gray-400 hover:text-blue-500"
                          >
                            <Edit2 size={14} />
                          </button>
                          <button 
                            onClick={() => handleDelete(ex.id)}
                            className="p-1.5 hover:bg-red-50 rounded-lg text-gray-400 hover:text-red-500"
                          >
                            <Trash2 size={14} />
                          </button>
                        </div>
                      </div>

                      {isExpanded && embedUrl && (
                        <div className="px-3 pb-3 pt-0 animate-in slide-in-from-top-2 duration-200">
                          <div className="relative aspect-video w-full rounded-lg overflow-hidden bg-black border border-gray-200">
                            <iframe
                              src={embedUrl}
                              className="w-full h-full"
                              frameBorder="0"
                              allowFullScreen
                            />
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

