import React, { useState, useRef, useEffect } from 'react';
import { 
  Plus, 
  Trash2, 
  ChevronDown, 
  ChevronRight, 
  GripVertical,
  PlayCircle,
  X,
  Search,
  Check,
  PlusCircle,
  Play,
  ArrowLeft,
  ArrowRight,
  Video
} from 'lucide-react';
import { Routine, Exercise, Category, ExerciseItem, SubRoutine } from '../types.ts';

interface RoutineBuilderProps {
  routines: Routine[];
  setRoutines: React.Dispatch<React.SetStateAction<Routine[]>>;
  exercises: Exercise[];
  setExercises: React.Dispatch<React.SetStateAction<Exercise[]>>;
  categories: Category[];
}

const getYoutubeEmbedUrl = (url: string) => {
  const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
  const match = url.match(regExp);
  const id = (match && match[2].length === 11) ? match[2] : null;
  return id ? `https://www.youtube.com/embed/${id}?rel=0&modestbranding=1&enablejsapi=1` : null;
};

/**
 * Focus Mode Component for playing a routine
 * Optimized for Gym environment: Big, Centered, High-Contrast
 */
const FocusMode: React.FC<{
  routine: Routine;
  exercises: Exercise[];
  categories: Category[];
  onClose: () => void;
}> = ({ routine, exercises, categories, onClose }) => {
  const sequence = [
    ...routine.exerciseItems.map(item => ({ ...item, section: 'Main' })),
    ...routine.subRoutines.flatMap(sr => sr.exerciseItems.map(item => ({ ...item, section: sr.name })))
  ];

  const [currentIndex, setCurrentIndex] = useState(0);
  const [showVideo, setShowVideo] = useState(false);
  const [touchStart, setTouchStart] = useState<number | null>(null);

  const next = () => {
    if (currentIndex < sequence.length - 1) {
      setCurrentIndex(prev => prev + 1);
      setShowVideo(false);
    }
  };
  const prev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
      setShowVideo(false);
    }
  };

  const handleTouchStart = (e: React.TouchEvent) => setTouchStart(e.targetTouches[0].clientX);
  const handleTouchEnd = (e: React.TouchEvent) => {
    if (touchStart === null) return;
    const touchEnd = e.changedTouches[0].clientX;
    const distance = touchStart - touchEnd;
    if (distance > 70) next();
    if (distance < -70) prev();
    setTouchStart(null);
  };

  const currentItem = sequence[currentIndex];
  const ex = exercises.find(e => e.id === currentItem?.exerciseId);
  const embedUrl = ex?.videoUrl ? getYoutubeEmbedUrl(ex.videoUrl) : null;

  if (sequence.length === 0) return (
    <div className="fixed inset-0 z-[200] bg-white flex flex-col items-center justify-center p-6 text-center">
      <p className="text-gray-400 font-bold mb-4 uppercase tracking-widest">Routine is empty</p>
      <button onClick={onClose} className="px-10 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl">Back to Builder</button>
    </div>
  );

  return (
    <div 
      className="fixed inset-0 z-[200] bg-white flex flex-col animate-in fade-in slide-in-from-bottom-6 duration-500"
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
    >
      {/* Header Overlay */}
      <header className="px-6 py-4 flex items-center justify-between shrink-0 bg-white/80 backdrop-blur-md z-10">
        <div className="flex flex-col">
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">{routine.name}</p>
          <div className="flex items-center gap-2">
            <span className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" />
            <p className="text-xs font-black text-blue-600 uppercase tracking-widest">Set {currentIndex + 1} of {sequence.length}</p>
          </div>
        </div>
        <button onClick={onClose} className="w-12 h-12 flex items-center justify-center bg-gray-100 hover:bg-gray-200 rounded-full text-gray-400 transition-colors"><X size={28} /></button>
      </header>

      {/* Main Content Area - Fully Centered Stack */}
      <div className="flex-1 flex flex-col items-center justify-center px-8 py-12 overflow-y-auto text-center space-y-12 bg-gradient-to-b from-white to-gray-50">

        {/* Line 1: The Name */}
        <div className="space-y-2 animate-in fade-in zoom-in-95 duration-500">
          <span className="inline-block text-[10px] font-black text-blue-500 bg-blue-50 px-4 py-1.5 rounded-full uppercase tracking-[0.2em] mb-4">
            {currentItem.section}
          </span>
          <h1 className="text-4xl sm:text-6xl font-black text-gray-900 leading-tight tracking-tight">
            {ex?.title}
          </h1>
        </div>

        {/* Line 2: The Comment / Description */}
        <div className="max-w-2xl w-full animate-in fade-in slide-in-from-top-4 delay-150 duration-500">
          <div className="p-8 bg-white rounded-[2.5rem] shadow-2xl shadow-gray-200/50 border border-gray-100">
            <p className="text-xl sm:text-2xl text-gray-600 leading-relaxed font-medium">
              {ex?.description || "Focus on form and controlled movement."}
            </p>
          </div>
        </div>

        {/* Line 3: The Video Button */}
        {embedUrl && (
          <div className="animate-in fade-in slide-in-from-top-4 delay-300 duration-500">
            <button 
              onClick={() => setShowVideo(true)}
              className="flex items-center gap-3 px-8 py-4 bg-gray-900 text-white rounded-2xl font-black uppercase tracking-widest hover:scale-105 transition-all shadow-2xl shadow-gray-400/30"
            >
              <Video size={20} /> Watch Video
            </button>
          </div>
        )}

        {/* Line 4: The Categories */}
        <div className="flex flex-wrap justify-center gap-2 animate-in fade-in delay-500 duration-500">
          {ex?.categories.map(cat => (
            <span key={cat} className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-[0.1em] text-white shadow-sm ${categories.find(c => c.name === cat)?.color || 'bg-gray-400'}`}>
              {cat}
            </span>
          ))}
        </div>
      </div>

      {/* Footer Controls */}
      <footer className="p-6 sm:p-8 bg-white border-t flex gap-4 shrink-0 shadow-[0_-10px_40px_rgba(0,0,0,0.03)]">
        <button 
          onClick={prev} 
          disabled={currentIndex === 0} 
          className="flex-1 py-5 bg-gray-100 text-gray-400 hover:bg-gray-200 hover:text-gray-600 rounded-[2rem] font-black uppercase tracking-widest disabled:opacity-20 transition-all flex items-center justify-center gap-3"
        >
          <ArrowLeft size={24} /> <span className="hidden sm:inline">Previous</span>
        </button>
        <button 
          onClick={next} 
          disabled={currentIndex === sequence.length - 1} 
          className="flex-[2.5] py-5 bg-blue-600 text-white rounded-[2rem] font-black uppercase tracking-widest disabled:opacity-20 transition-all shadow-2xl shadow-blue-200 flex items-center justify-center gap-3 active:scale-[0.98]"
        >
          {currentIndex === sequence.length - 1 ? "Finish Routine" : "Next Exercise"} <ArrowRight size={24} />
        </button>
      </footer>

      {/* Video Modal */}
      {showVideo && embedUrl && (
        <div className="fixed inset-0 z-[250] bg-black/95 flex flex-col items-center justify-center p-4 animate-in fade-in duration-300">
          <button 
            onClick={() => setShowVideo(false)}
            className="absolute top-8 right-8 w-14 h-14 bg-white/10 hover:bg-white/20 text-white rounded-full flex items-center justify-center backdrop-blur-md transition-all z-[260]"
          >
            <X size={32} />
          </button>
          <div className="w-full max-w-5xl aspect-video bg-black rounded-3xl overflow-hidden shadow-2xl">
            <iframe src={embedUrl} className="w-full h-full" frameBorder="0" allowFullScreen />
          </div>
          <p className="mt-6 text-white/60 font-black uppercase tracking-[0.2em] text-sm">Tap outside or close to return</p>
          <div className="absolute inset-0 -z-10" onClick={() => setShowVideo(false)} />
        </div>
      )}
    </div>
  );
};

const CompactExerciseRow: React.FC<{ 
  exerciseId: number; 
  onRemove: () => void; 
  exercises: Exercise[]; 
  categories: Category[];
  routineId: number;
  subRoutineId?: number;
  index: number;
