              {(ex.categories || []).map(cat => (
                <span key={cat} className={`px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-wider text-white ${categories.find(c => c.name === cat)?.color || 'bg-gray-400'}`}>{cat}</span>
